{
  "version": 1,
  "kind": "http",
  "http": true,
  "probe": {
    "request": { "method": "GET", "url": "https://site.example/api/me" },
    "expect": { "status": [200] }
  },
  "login": {
    "steps": [
      {
        "id": "csrf_prefetch",
        "request": { "method": "GET", "url": "https://site.example/login" },
        "extract": {
          "csrf": { "from": "html_css", "selector": "input[name=_csrf]", "attribute": "value" }
        },
        "expect": { "status": [200] }
      },
      {
        "id": "credentials",
        "request": {
          "method": "POST",
          "url": "https://site.example/api/login",
          "headers": { "Content-Type": "application/x-www-form-urlencoded" },
          "body": "username={{secret:username}}&password={{secret:password}}&_csrf={{extracted:csrf}}"
        },
        "extract": {
          "access": {
            "from": "json",
            "path": "$.token",
            "store": { "as": "header", "header": "Authorization", "prefix": "Bearer " }
          }
        },
        "expect": { "status": [200, 302], "not_url_patterns": ["/login"] },
        "challenges": [
          {
            "type": "totp",
            "detect": { "status": [401], "body_regex": "two.?factor|totp|verification code" },
            "submit": {
              "method": "POST",
              "url": "https://site.example/api/login/2fa",
              "headers": { "Content-Type": "application/json" },
              "body": "{\"code\":\"{{challenge:code}}\"}"
            },
            "expect": { "status": [200] },
            "max_wait_seconds": 60
          }
        ]
      }
    ],
    "tokens": {
      "access": { "header": "Authorization", "prefix": "Bearer ", "value": "{{extracted:access}}" }
    }
  },
  "refresh": {
    "request": {
      "method": "POST",
      "url": "https://site.example/oauth/token",
      "headers": { "Content-Type": "application/json" },
      "body": "{\"refresh_token\":\"{{token:refresh_token}}\"}"
    },
    "extract": {
      "access": {
        "from": "json",
        "path": "$.access_token",
        "store": { "as": "header", "header": "Authorization", "prefix": "Bearer " }
      }
    },
    "expect": { "status": [200] }
  },
  "stale": {
    "status": [401, 403],
    "url_patterns": ["/login", "/signin"],
    "html_when_json_expected": true
  }
}

use anyhow::Result;
use playwright_rs::Page;

pub async fn click_at(page: &Page, x: f64, y: f64) -> Result<()> {
    tracing::debug!(x, y, "click_at");
    page.mouse().click(x as i32, y as i32, None).await
        .map_err(|e| anyhow::anyhow!("Click at ({}, {}) failed: {}", x, y, e))
}

pub async fn click_selector(page: &Page, selector: &str, force: bool) -> Result<()> {
    tracing::debug!(selector, force, "click_selector");
    let locator = page.locator(selector).await;
    let mut opts = playwright_rs::ClickOptions::default();
    if force {
        opts.force = Some(true);
    }
    locator.click(Some(opts)).await
        .map_err(|e| anyhow::anyhow!("Click '{}' failed: {}", selector, e))
}

pub async fn fill(page: &Page, selector: &str, value: &str) -> Result<()> {
    tracing::debug!(selector, value_len = value.len(), "fill");
    let locator = page.locator(selector).await;
    locator.fill(value, None).await
        .map_err(|e| anyhow::anyhow!("Fill '{}' failed: {}", selector, e))
}

pub async fn clear_and_type(page: &Page, selector: &str, value: &str, delay_ms: f64) -> Result<()> {
    tracing::debug!(selector, value_len = value.len(), delay_ms, "clear_and_type");
    let locator = page.locator(selector).await;
    locator.click(None).await
        .map_err(|e| anyhow::anyhow!("Focus click failed: {}", e))?;

    // Select all + delete to clear
    page.keyboard().press("Control+a", None).await
        .map_err(|e| anyhow::anyhow!("Ctrl+A failed: {}", e))?;
    page.keyboard().press("Delete", None).await
        .map_err(|e| anyhow::anyhow!("Delete failed: {}", e))?;

    // Type with per-character delay
    let kb_opts = playwright_rs::protocol::action_options::KeyboardOptions {
        delay: Some(delay_ms),
    };
    page.keyboard().type_text(value, Some(kb_opts)).await
        .map_err(|e| anyhow::anyhow!("Type failed: {}", e))
}

pub async fn select_option(page: &Page, selector: &str, value: &str) -> Result<()> {
    // Never log/echo the value — it may be a resolved credential (log its length only, like fill).
    tracing::debug!(selector, value_len = value.len(), "select_option");
    let locator = page.locator(selector).await;

    // Try by value first
    match locator.select_option(playwright_rs::SelectOption::Value(value.to_string()), None).await {
        Ok(_) => Ok(()),
        Err(_) => {
            // Fallback: try by label
            locator.select_option(playwright_rs::SelectOption::Label(value.to_string()), None).await
                .map(|_| ())
                .map_err(|e| anyhow::anyhow!("Select option on '{}' failed: {}", selector, e))
        }
    }
}

pub async fn check(page: &Page, selector: &str) -> Result<()> {
    tracing::debug!(selector, "check");
    let locator = page.locator(selector).await;
    locator.check(None).await
        .map_err(|e| anyhow::anyhow!("Check '{}' failed: {}", selector, e))
}

pub async fn uncheck(page: &Page, selector: &str) -> Result<()> {
    tracing::debug!(selector, "uncheck");
    let locator = page.locator(selector).await;
    locator.uncheck(None).await
        .map_err(|e| anyhow::anyhow!("Uncheck '{}' failed: {}", selector, e))
}

pub async fn hover(page: &Page, selector: &str) -> Result<()> {
    tracing::debug!(selector, "hover");
    let locator = page.locator(selector).await;
    locator.hover(None).await
        .map_err(|e| anyhow::anyhow!("Hover '{}' failed: {}", selector, e))
}

pub async fn hover_at(page: &Page, x: f64, y: f64) -> Result<()> {
    tracing::debug!(x, y, "hover_at");
    page.mouse().move_to(x as i32, y as i32, None).await
        .map_err(|e| anyhow::anyhow!("Mouse move to ({}, {}) failed: {}", x, y, e))
}

pub async fn focus(page: &Page, selector: &str) -> Result<()> {
    tracing::debug!(selector, "focus");
    let locator = page.locator(selector).await;
    locator.focus().await
        .map_err(|e| anyhow::anyhow!("Focus '{}' failed: {}", selector, e))
}

pub async fn scroll_into_view(page: &Page, selector: &str) -> Result<()> {
    tracing::debug!(selector, "scroll_into_view");
    let locator = page.locator(selector).await;
    locator.scroll_into_view_if_needed().await
        .map_err(|e| anyhow::anyhow!("Scroll into view '{}' failed: {}", selector, e))
}

pub async fn keyboard_type(page: &Page, text: &str, delay_ms: f64) -> Result<()> {
    tracing::debug!(len = text.len(), delay_ms, "keyboard_type");
    let kb_opts = playwright_rs::protocol::action_options::KeyboardOptions {
        delay: Some(delay_ms),
    };
    page.keyboard().type_text(text, Some(kb_opts)).await
        .map_err(|e| anyhow::anyhow!("Keyboard type failed: {}", e))
}

pub async fn keyboard_press(page: &Page, key: &str) -> Result<()> {
    tracing::debug!(key, "keyboard_press");
    page.keyboard().press(key, None).await
        .map_err(|e| anyhow::anyhow!("Keyboard press '{}' failed: {}", key, e))
}

pub async fn mouse_wheel(page: &Page, delta_x: f64, delta_y: f64) -> Result<()> {
    // Diagnostic: time the driver round-trip. During scroll the wheel response
    // shares the single Playwright driver pipe with screencast frames, so a high
    // elapsed_ms here is head-of-line blocking behind frames, not the browser.
    let started = std::time::Instant::now();
    let r = page.mouse().wheel(delta_x as i32, delta_y as i32).await
        .map_err(|e| anyhow::anyhow!("Mouse wheel failed: {}", e));
    tracing::debug!(delta_x, delta_y, elapsed_ms = started.elapsed().as_millis() as u64, "mouse_wheel");
    r
}

pub async fn mouse_click(page: &Page, x: f64, y: f64, button: &str) -> Result<()> {
    tracing::debug!(x, y, button, "mouse_click");
    let opts = playwright_rs::protocol::action_options::MouseOptions {
        button: Some(match button {
            "right" => playwright_rs::protocol::click::MouseButton::Right,
            "middle" => playwright_rs::protocol::click::MouseButton::Middle,
            _ => playwright_rs::protocol::click::MouseButton::Left,
        }),
        ..Default::default()
    };
    page.mouse().click(x as i32, y as i32, Some(opts)).await
        .map_err(|e| anyhow::anyhow!("Mouse click failed: {}", e))
}

pub async fn dispatch_event(page: &Page, selector: &str, event_type: &str) -> Result<()> {
    tracing::debug!(selector, event_type, "dispatch_event");
    let locator = page.locator(selector).await;
    locator.dispatch_event(event_type, None).await
        .map_err(|e| anyhow::anyhow!("Dispatch event '{}' on '{}' failed: {}", event_type, selector, e))
}

pub async fn set_input_files(page: &Page, selector: &str, files: Vec<String>) -> Result<()> {
    tracing::debug!(selector, count = files.len(), "set_input_files");
    let locator = page.locator(selector).await;
    let paths: Vec<std::path::PathBuf> = files.iter().map(std::path::PathBuf::from).collect();
    if paths.len() == 1 {
        locator.set_input_files(&paths[0], None).await
            .map_err(|e| anyhow::anyhow!("Set input files failed: {}", e))
    } else {
        let path_refs: Vec<&std::path::PathBuf> = paths.iter().collect();
        locator.set_input_files_multiple(&path_refs, None).await
            .map_err(|e| anyhow::anyhow!("Set input files failed: {}", e))
    }
}

pub async fn bounding_box(page: &Page, selector: &str) -> Result<Option<(f64, f64, f64, f64)>> {
    let locator = page.locator(selector).await;
    match locator.bounding_box().await {
        Ok(Some(bb)) => Ok(Some((bb.x, bb.y, bb.width, bb.height))),
        Ok(None) => Ok(None),
        Err(e) => Err(anyhow::anyhow!("Bounding box failed: {}", e)),
    }
}

//! Transport-neutral ephemeral agent-action executor.
//!
//! Executes AI-driven action(s) on a live page WITHOUT recording workflow steps, then builds a
//! compact next-decision observation. Extracted verbatim out of the cloud `bridge/saas_bridge.rs`
//! so both the cloud recorder AND the local AI-assist recording session drive the SAME executor —
//! the page-execution + observation contract must match exactly. Its dependencies are all neutral
//! (`crate::ai::action_executor`, `crate::browser::*`, `crate::security::url_guard`,
//! `crate::bridge::otp_entry`, `crate::dom::analyzer`), so this module carries NO cloud coupling
//! and stays in the KEEP set (compiles under `local,fleet`).

use std::collections::HashMap;

/// PageEvaluator adapter so the DOM analyzer can run against a live page.
/// Mirrors the private adapter in ai/intelligent_mode.rs.
struct AgentPageEvaluator<'a>(&'a playwright_rs::Page);

impl<'a> crate::dom::analyzer::PageEvaluator for AgentPageEvaluator<'a> {
    fn evaluate_json(
        &self,
        js: &str,
    ) -> std::pin::Pin<Box<dyn std::future::Future<Output = anyhow::Result<serde_json::Value>> + Send + '_>> {
        let js = js.to_string();
        Box::pin(async move {
            let result: serde_json::Value = self.0.evaluate(&js, None::<&()>).await
                .map_err(|e| anyhow::anyhow!("evaluate_json failed: {}", e))?;
            Ok(result)
        })
    }

    fn evaluate_json_with_args(
        &self,
        js: &str,
        args: &[serde_json::Value],
    ) -> std::pin::Pin<Box<dyn std::future::Future<Output = anyhow::Result<serde_json::Value>> + Send + '_>> {
        let js = js.to_string();
        let args = serde_json::Value::Array(args.to_vec());
        Box::pin(async move {
            let result: serde_json::Value = self.0.evaluate(&js, Some(&args)).await
                .map_err(|e| anyhow::anyhow!("evaluate_json_with_args failed: {}", e))?;
            Ok(result)
        })
    }
}

/// Execute AI-driven action(s) on the live page WITHOUT recording workflow steps.
/// Accepts a batch via `actions: [...]`, a nested `action: {...}`, or a flat
/// `action: "click"` with sibling params. Returns (results, observation).
/// The page is already cloned out of the session — this fn never touches the
/// DashMap, so it holds no lock across its `.await`s.
// `pub` (re-exported at `crate::automation::run_agent_actions`) so BOTH the cloud recorder and the
// local daemon's recording session drive the SAME ephemeral agent-action executor — the local
// AI-assist brain runs the decision loop on the user's own provider, but the page-execution +
// observation contract must match exactly.
pub async fn run_agent_actions(
    page: &playwright_rs::Page,
    msg: &serde_json::Value,
    read_only: bool,
) -> (Vec<serde_json::Value>, serde_json::Value) {
    // Normalize incoming shapes into a list of action objects.
    let mut actions: Vec<serde_json::Value> = Vec::new();
    if let Some(arr) = msg.get("actions").and_then(|v| v.as_array()) {
        actions = arr.iter().filter(|a| a.is_object()).cloned().collect();
    } else {
        match msg.get("action") {
            Some(a @ serde_json::Value::Object(_)) => actions.push(a.clone()),
            Some(serde_json::Value::String(a)) => {
                // Flat form: lift sibling params into a single action object.
                let mut flat = serde_json::Map::new();
                if let Some(obj) = msg.as_object() {
                    for (k, v) in obj {
                        if k != "type" && k != "request_id" && k != "actions" {
                            flat.insert(k.clone(), v.clone());
                        }
                    }
                }
                flat.insert("action".to_string(), serde_json::Value::String(a.clone()));
                actions.push(serde_json::Value::Object(flat));
            }
            _ => {}
        }
    }

    // Pure observation request (model just wants fresh page context).
    if actions.is_empty() {
        return (Vec::new(), safe_observation(page, None).await);
    }

    // Initial DOM state (fields/buttons with coordinates) for index/coord actions.
    let mut dom_state: serde_json::Value = safe_dom_state(page).await;

    // RELIABILITY (mirrors the Python recorder): the runner waits
    // _AGENT_ACTION_TIMEOUT (120s) for agent_action_result, so we MUST return a
    // (possibly partial) batch BEFORE then — a runner-side timeout yields NO result
    // at all. Bound the whole batch and every individual action.
    let deadline = std::time::Instant::now() + std::time::Duration::from_secs_f64(BATCH_BUDGET);

    let mut results: Vec<serde_json::Value> = Vec::new();
    for act in actions.iter().take(25) {
        let atype = act.get("action").and_then(|v| v.as_str()).unwrap_or("").trim().to_string();
        let label = if atype.is_empty() { "(missing)".to_string() } else { atype.clone() };

        // Out of overall budget → report remaining actions as skipped.
        let remaining = deadline.saturating_duration_since(std::time::Instant::now());
        if remaining.is_zero() {
            results.push(serde_json::json!(
                {"action": label, "success": false, "error": "skipped: batch time budget exhausted"}));
            continue;
        }

        // Per-action hard budget, clamped to the time left so one action can't eat
        // the rest. A single hang (navigation that never settles, detached context,
        // missing selector) can NEVER wedge the batch — it becomes a timeout result.
        let budget = action_budget(act)
            .min(remaining)
            .max(std::time::Duration::from_secs(1));
        let res = match tokio::time::timeout(budget, run_one_agent_action(page, act, &dom_state, read_only)).await {
            Ok(v) => v,
            Err(_) => serde_json::json!({
                "action": label, "success": false,
                "error": format!("action timed out after {:.0}s", budget.as_secs_f64()),
            }),
        };
        results.push(res);

        // After a potentially page-changing action, settle deterministically then
        // refresh the DOM snapshot for the NEXT action's selectors.
        if matches!(
            atype.as_str(),
            "click" | "check" | "submit" | "navigate" | "press_key"
                | "scroll" | "back" | "evaluate_js" | "select" | "fill" | "type_text" | "type"
        ) {
            let navigated = matches!(
                atype.as_str(),
                "click" | "submit" | "navigate" | "press_key" | "back"
            );
            settle_page(page, navigated).await;
            dom_state = safe_dom_state(page).await;
        }
    }

    let observation = safe_observation(page, Some(&dom_state)).await;
    (results, observation)
}

/// Wall-clock ceiling for one agent_action batch. Kept comfortably under the
/// runner's _AGENT_ACTION_TIMEOUT (120s) with room for the final observation.
const BATCH_BUDGET: f64 = 95.0;

lazy_static::lazy_static! {
    /// Side-effecting JS patterns blocked by the read-only evaluate_js guard for
    /// autonomous AI sessions. Mirrors the Python recorder `_JS_WRITE_PATTERNS`.
    /// NOTE: the `regex` crate has no look-around, so assignment guards use
    /// `=(?:[^=]|$)` (an `=` NOT followed by another `=`) to skip ==/===/!=.
    static ref JS_WRITE_RE: Vec<(regex::Regex, &'static str)> = {
        let pats: &[(&str, &str)] = &[
            (r"\.click\s*\(", "DOM click()"),
            (r"\.submit\s*\(", "form submit()"),
            (r"\.dispatchEvent\s*\(", "dispatchEvent()"),
            (r"\.value\s*=(?:[^=]|$)", "writing .value"),
            (r"\.checked\s*=(?:[^=]|$)", "writing .checked"),
            (r"\.selected\s*=(?:[^=]|$)", "writing .selected"),
            (r"\.innerHTML\s*=(?:[^=]|$)", "writing .innerHTML"),
            (r"\.outerHTML\s*=(?:[^=]|$)", "writing .outerHTML"),
            (r"\.innerText\s*=(?:[^=]|$)", "writing .innerText"),
            (r"\.textContent\s*=(?:[^=]|$)", "writing .textContent"),
            (r"\.setAttribute\s*\(", "setAttribute()"),
            (r"\.removeAttribute\s*\(", "removeAttribute()"),
            (r"\.(?:append|prepend|before|after|replaceChildren|replaceWith|remove)\s*\(", "DOM tree mutation"),
            (r"\.(?:appendChild|removeChild|insertBefore|replaceChild)\s*\(", "DOM tree mutation"),
            (r"\bWebSocket\b", "WebSocket"),
            (r"\bEventSource\b", "EventSource"),
            (r"\bwindow\.open\s*\(", "window.open()"),
            (r"\blocation\s*=(?:[^=]|$)", "location assignment"),
            (r"\blocation\.(?:href|assign|replace|reload)\b", "navigation via location"),
            (r"\bhistory\.(?:pushState|replaceState|go|back|forward)\b", "history navigation"),
            (r"\b(?:localStorage|sessionStorage)\.(?:setItem|removeItem|clear)\b", "storage write"),
            (r"document\.cookie\s*=(?:[^=]|$)", "cookie write"),
            (r"\beval\s*\(", "eval()"),
            (r"\bnew\s+Function\b", "Function constructor"),
            (r"\bimport\s*\(", "dynamic import()"),
        ];
        pats.iter().map(|(p, w)| (regex::Regex::new(p).unwrap(), *w)).collect()
    };
}

/// Return a reason if `script` would mutate the page, navigate, hit the network, or
/// write storage — i.e. is NOT read-only. None for read-only scripts. Heuristic by
/// design; a false-positive just nudges the brain to use the structured action.
fn js_write_violation(script: &str) -> Option<&'static str> {
    if script.is_empty() {
        return None;
    }
    for (rx, why) in JS_WRITE_RE.iter() {
        if rx.is_match(script) {
            return Some(why);
        }
    }
    None
}

/// Per-action hard timeout. Generous for real page work, tight enough that a stuck
/// action can't outlive the runner. `wait` is bounded by its own requested duration.
fn action_budget(act: &serde_json::Value) -> std::time::Duration {
    use std::time::Duration;
    let atype = act.get("action").and_then(|v| v.as_str()).unwrap_or("").trim();
    match atype {
        "wait" => {
            let s = act.get("seconds").and_then(|v| v.as_f64()).unwrap_or(1.0).clamp(0.0, 10.0);
            Duration::from_secs_f64(s + 5.0)
        }
        "navigate" | "back" => Duration::from_secs(35), // full document load
        "click" | "submit" | "press_key" => Duration::from_secs(20),
        "get_screenshot" => Duration::from_secs(20),
        _ => Duration::from_secs(15), // fill/type/select/check/read/evaluate/etc.
    }
}

/// Deterministically let the page settle after a mutating action, fully bounded so
/// it can never hang. Navigating actions wait for the new document; all allow a
/// brief network-quiet window so SPA/XHR re-renders land before the next selector.
async fn settle_page(page: &playwright_rs::Page, navigated: bool) {
    use std::time::Duration;
    if navigated {
        let _ = tokio::time::timeout(
            Duration::from_secs(8),
            crate::browser::navigation::wait_for_load_state(page, "domcontentloaded", Duration::from_secs(8)),
        )
        .await;
    }
    // networkidle can stall on long-poll/streaming pages, so keep it short and
    // treat a timeout as "settled enough".
    let _ = tokio::time::timeout(
        Duration::from_millis(2500),
        crate::browser::navigation::wait_for_load_state(page, "networkidle", Duration::from_millis(2500)),
    )
    .await;
}

/// DOM field/button snapshot, bounded — never hangs on a navigating page.
async fn safe_dom_state(page: &playwright_rs::Page) -> serde_json::Value {
    match tokio::time::timeout(
        std::time::Duration::from_secs(8),
        crate::browser::page_query::evaluate(page, crate::ai::action_executor::DOM_FIELDS_WITH_COORDS_JS),
    )
    .await
    {
        Ok(Ok(v)) => v,
        _ => serde_json::json!({"fields": [], "buttons": []}),
    }
}

/// Build the next-decision observation under a hard cap. Every page.evaluate inside
/// auto-waits for navigation and could otherwise hang; on timeout return a minimal
/// observation so the agent still gets a reply and can re-observe.
async fn safe_observation(
    page: &playwright_rs::Page,
    dom_state: Option<&serde_json::Value>,
) -> serde_json::Value {
    match tokio::time::timeout(
        std::time::Duration::from_secs(12),
        build_agent_observation(page, dom_state),
    )
    .await
    {
        Ok(v) => v,
        Err(_) => serde_json::json!({
            "current_url": page.url(),
            "fields": [], "buttons": [], "page_text": "", "errors": [],
            "a11y": {"viewport": {}, "elements": []},
        }),
    }
}

/// Execute one ephemeral action. Prefers selector / JS / navigation for full
/// browser control; falls back to the intelligent-mode executor for
/// field_index / coordinate based actions. Never records a workflow step.
async fn run_one_agent_action(
    page: &playwright_rs::Page,
    act: &serde_json::Value,
    dom_state: &serde_json::Value,
    read_only: bool,
) -> serde_json::Value {
    use crate::browser::{navigation, page_actions, page_query};
    use std::time::Duration;

    let atype = act
        .get("action")
        .and_then(|v| v.as_str())
        .unwrap_or("")
        .trim()
        .to_string();
    let selector = act.get("selector").and_then(|v| v.as_str());

    let result: anyhow::Result<serde_json::Value> = async {
        match atype.as_str() {
            "navigate" => {
                let url = act.get("url").and_then(|v| v.as_str())
                    .or_else(|| act.get("value").and_then(|v| v.as_str()));
                let url = match url {
                    Some(u) => u,
                    None => return Ok(serde_json::json!(
                        {"action": atype, "success": false, "error": "navigate requires url"})),
                };
                // SSRF guard (fail-CLOSED): the cloud drives this navigation, so vet the target before
                // `goto` — a malicious/compromised dispatcher must not reach loopback/metadata/LAN.
                if !crate::security::url_guard::is_navigation_url_safe_async(url).await {
                    return Ok(serde_json::json!(
                        {"action": atype, "success": false, "error": "navigate blocked: unsafe URL"}));
                }
                navigation::goto(page, url, "domcontentloaded", Duration::from_secs(30)).await?;
                Ok(serde_json::json!({"action": atype, "success": true, "url": page.url()}))
            }
            "back" => {
                // `false` = no history entry. Report it so the AI sees a refused
                // action and picks another move instead of looping on a no-op it
                // was told succeeded.
                let moved = navigation::go_back(page, Duration::from_secs(30)).await?;
                Ok(serde_json::json!({
                    "action": atype,
                    "success": moved,
                    "url": page.url(),
                    "error": if moved { serde_json::Value::Null } else { serde_json::json!("no history entry to go back to") },
                }))
            }
            "twofa_enter" => {
                // Runner-internal: the 2FA code was minted SERVER-SIDE and handed to
                // us here. Enter it via the shared robust OTP JS (single/segmented/
                // contenteditable/paste). NEVER echo the code — only {ok, kind, filled}.
                // Its own action arm, so the evaluate_js read-only guard never applies.
                let code = act.get("code").and_then(|v| v.as_str()).unwrap_or("");
                let kind = act.get("kind").and_then(|v| v.as_str()).unwrap_or("code");
                let mut sel = act.get("selector").and_then(|v| v.as_str())
                    .filter(|s| !s.is_empty()).map(|s| s.to_string());
                let submit = act.get("submit_selector").and_then(|v| v.as_str())
                    .filter(|s| !s.is_empty()).map(|s| s.to_string());
                if kind == "magic_link" {
                    // Fail-CLOSED: a magic link is a navigation target driven by the cloud.
                    if !crate::security::url_guard::is_navigation_url_safe_async(code).await {
                        return Ok(serde_json::json!({"action": atype, "success": false,
                            "error": "magic-link blocked: unsafe URL"}));
                    }
                    navigation::goto(page, code, "domcontentloaded", Duration::from_secs(30)).await?;
                    return Ok(serde_json::json!({"action": atype, "success": true, "ok": true, "kind": "magic_link"}));
                }
                let mut detected_submit: Option<String> = None;
                if sel.is_none() {
                    if let Ok(det) = page_query::evaluate::<serde_json::Value>(
                        page, &crate::bridge::otp_entry::detect_invocation()).await
                    {
                        sel = det.get("selector").and_then(|v| v.as_str())
                            .filter(|s| !s.is_empty()).map(|s| s.to_string());
                        detected_submit = det.get("submit_selector").and_then(|v| v.as_str()).map(|s| s.to_string());
                    }
                }
                let entry_js = crate::bridge::otp_entry::entry_invocation(code, sel.as_deref());
                let res: serde_json::Value = page_query::evaluate(page, &entry_js).await
                    .unwrap_or_else(|_| serde_json::json!({"ok": false}));
                let ok = res.get("ok").and_then(|v| v.as_bool()).unwrap_or(false);
                let res_kind = res.get("kind").and_then(|v| v.as_str()).unwrap_or(kind).to_string();
                let filled = res.get("filled").and_then(|v| v.as_i64()).unwrap_or(0);
                if let Some(submit) = submit.or(detected_submit) {
                    let _ = page_actions::click_selector(page, &submit, false).await;
                }
                Ok(serde_json::json!({"action": atype, "success": ok, "ok": ok, "kind": res_kind, "filled": filled}))
            }
            "evaluate_js" => {
                let script = act.get("script").and_then(|v| v.as_str())
                    .or_else(|| act.get("value").and_then(|v| v.as_str()))
                    .unwrap_or("");
                // READ-ONLY guard for autonomous AI sessions: inspect the DOM freely
                // but reject any script that mutates the page, clicks, navigates,
                // hits the network, or writes storage. Interaction must use the
                // structured fill/click/... actions (which substitute {{secret:}} and
                // get recorded). Interactive scraper-builder (read_only=false) keeps
                // full raw JS. Mirrors the Python recorder _js_write_violation gate.
                if read_only {
                    if let Some(why) = js_write_violation(script) {
                        return Ok(serde_json::json!({
                            "action": atype, "success": false,
                            "error": format!(
                                "evaluate_js is READ-ONLY in AI sessions: {}. Use the structured \
                                 actions (fill/click/select/press_key/...) to interact with the page.",
                                why),
                        }));
                    }
                }
                // page.evaluate accepts an expression. Function bodies (with `return`)
                // are wrapped in an IIFE; expression/IIFE forms run as-is.
                let s = script.trim();
                let expr = if s.starts_with('(') {
                    script.to_string()
                } else if script.contains("return") {
                    format!("(() => {{ {} }})()", script)
                } else {
                    script.to_string()
                };
                let eval_result: serde_json::Value = page_query::evaluate(page, &expr).await?;
                Ok(serde_json::json!({"action": atype, "success": true, "eval_result": eval_result}))
            }
            "click" | "check" if selector.is_some() => {
                page_actions::click_selector(page, selector.unwrap(), false).await?;
                Ok(serde_json::json!({"action": atype, "success": true, "selector": selector}))
            }
            "fill" | "type_text" if selector.is_some() => {
                let value = act.get("value").and_then(|v| v.as_str()).unwrap_or("");
                page_actions::fill(page, selector.unwrap(), value).await?;
                Ok(serde_json::json!({"action": atype, "success": true, "selector": selector}))
            }
            "select" if selector.is_some() => {
                let value = act.get("value").and_then(|v| v.as_str()).unwrap_or("");
                page_actions::select_option(page, selector.unwrap(), value).await?;
                Ok(serde_json::json!({"action": atype, "success": true, "selector": selector}))
            }
            "press_key" => {
                let key = act.get("key").and_then(|v| v.as_str()).unwrap_or("Enter");
                page_actions::keyboard_press(page, key).await?;
                Ok(serde_json::json!({"action": atype, "success": true}))
            }
            "scroll" => {
                let direction = act.get("direction").and_then(|v| v.as_str()).unwrap_or("down");
                let amount = act.get("amount").and_then(|v| v.as_f64()).unwrap_or(600.0);
                let delta_y = if direction == "up" { -amount } else { amount };
                page_actions::mouse_wheel(page, 0.0, delta_y).await?;
                Ok(serde_json::json!({"action": atype, "success": true}))
            }
            "wait" => {
                let seconds = act.get("seconds").and_then(|v| v.as_f64()).unwrap_or(1.0).min(10.0);
                tokio::time::sleep(Duration::from_secs_f64(seconds.max(0.0))).await;
                Ok(serde_json::json!({"action": atype, "success": true}))
            }
            "read_text" | "get_text" => {
                let txt = if let Some(sel) = selector {
                    page_query::locator_text_content(page, sel).await.ok().flatten().unwrap_or_default()
                } else {
                    page_query::evaluate::<serde_json::Value>(
                        page,
                        "() => document.body ? document.body.innerText : ''",
                    )
                    .await
                    .ok()
                    .and_then(|v| v.as_str().map(|s| s.to_string()))
                    .unwrap_or_default()
                };
                let txt: String = txt.chars().take(4000).collect();
                Ok(serde_json::json!({"action": atype, "success": true, "text": txt}))
            }
            // Fall back to the intelligent-mode executor (field_index / coordinates /
            // inspect_field / hover / submit / etc.). It returns a result without
            // recording a step.
            _ => {
                let fill_data: HashMap<String, String> = act
                    .get("fill_data")
                    .and_then(|v| serde_json::from_value(v.clone()).ok())
                    .unwrap_or_default();
                let r = crate::ai::action_executor::execute_and_verify_action(
                    page, act, &fill_data, dom_state,
                )
                .await;
                let mut obj = serde_json::Map::new();
                obj.insert("action".to_string(), serde_json::Value::String(atype.clone()));
                obj.insert("success".to_string(), serde_json::Value::Bool(r.success));
                if let Some(err) = &r.error {
                    obj.insert("error".to_string(), serde_json::Value::String(err.clone()));
                }
                if let Some(ep) = &r.endpoint {
                    obj.insert("endpoint".to_string(), ep.clone());
                }
                if let Some(actual) = &r.verification.actual {
                    obj.insert("result".to_string(), serde_json::Value::String(actual.clone()));
                }
                Ok(serde_json::Value::Object(obj))
            }
        }
    }
    .await;

    match result {
        Ok(v) => v,
        Err(e) => {
            let msg: String = e.to_string().chars().take(300).collect();
            serde_json::json!({"action": atype, "success": false, "error": msg})
        }
    }
}

/// Compact page context for the AI's next scraper-building decision.
/// Mirrors Python _build_agent_observation.
async fn build_agent_observation(
    page: &playwright_rs::Page,
    dom_state: Option<&serde_json::Value>,
) -> serde_json::Value {
    // Reuse provided DOM state or fetch fresh.
    let owned;
    let dom_state: &serde_json::Value = match dom_state {
        Some(d) => d,
        None => {
            owned = crate::browser::page_query::evaluate(
                page,
                crate::ai::action_executor::DOM_FIELDS_WITH_COORDS_JS,
            )
            .await
            .unwrap_or_else(|_| serde_json::json!({"fields": [], "buttons": []}));
            &owned
        }
    };

    // Page text + validation errors via the DOM analyzer.
    let mut page_text = String::new();
    let mut errors: Vec<serde_json::Value> = Vec::new();
    {
        let evaluator = AgentPageEvaluator(page);
        if let Ok(ctx) = crate::dom::analyzer::extract_page_context(&evaluator).await {
            if let Ok(val) = serde_json::to_value(&ctx) {
                if let Some(pt) = val.get("pageText").and_then(|v| v.as_array()) {
                    let joined: Vec<String> = pt
                        .iter()
                        .map(|t| {
                            if let Some(s) = t.as_str() {
                                s.to_string()
                            } else if let Some(s) = t.get("text").and_then(|v| v.as_str()) {
                                s.to_string()
                            } else {
                                t.to_string()
                            }
                        })
                        .collect();
                    page_text = joined.join("\n").chars().take(3000).collect();
                }
                if let Some(errs) = val.get("errors").and_then(|v| v.as_array()) {
                    errors = errs.iter().take(10).cloned().collect();
                }
            }
        }
    }

    let fields: Vec<serde_json::Value> = dom_state
        .get("fields")
        .and_then(|v| v.as_array())
        .map(|arr| {
            arr.iter()
                .take(40)
                .map(|f| {
                    serde_json::json!({
                        "index": f.get("index"),
                        "type": f.get("type"),
                        "label": f.get("label"),
                        "selector": f.get("selector"),
                        "value": f.get("value"),
                    })
                })
                .collect()
        })
        .unwrap_or_default();

    let buttons: Vec<serde_json::Value> = dom_state
        .get("buttons")
        .and_then(|v| v.as_array())
        .map(|arr| {
            arr.iter()
                .take(40)
                .enumerate()
                .map(|(i, b)| {
                    serde_json::json!({
                        "index": i,
                        "text": b.get("text"),
                        "selector": b.get("selector"),
                    })
                })
                .collect()
        })
        .unwrap_or_default();

    // Accessibility tree + viewport (coordinates) — the brain reads obs["a11y"]
    // for viewport + a11y_elements. Keep in lockstep with Python _build_a11y_tree.
    let a11y = crate::browser::page_query::evaluate(
        page,
        crate::ai::action_executor::A11Y_TREE_JS,
    )
    .await
    .unwrap_or_else(|_| serde_json::json!({"viewport": {}, "elements": []}));

    serde_json::json!({
        "current_url": page.url(),
        "fields": fields,
        "buttons": buttons,
        "page_text": page_text,
        "errors": errors,
        "a11y": a11y,
    })
}

use std::path::{Path, PathBuf};
use anyhow::{Context, Result};
use tracing::{info, warn};

/// Known cache directories where Playwright/Patchright store browser binaries.
const CACHE_DIRS: &[&str] = &[
    "~/.cache/ms-playwright",
    "~/.cache/patchright",
    "~/Library/Caches/ms-playwright",
    "~/Library/Caches/patchright",
    "/root/.cache/ms-playwright",
    "/root/.cache/patchright",
];

/// Chromium directory names to look for inside each cache dir.
const CHROMIUM_DIRS: &[&str] = &["chromium", "chromium-", "chrome"];

/// Expand `~` to the user's home directory.
fn expand_home(path: &str) -> PathBuf {
    if let Some(stripped) = path.strip_prefix("~/") {
        if let Some(home) = dirs_home() {
            return home.join(stripped);
        }
    }
    PathBuf::from(path)
}

/// The user's home directory.
///
/// `HOME` IS NOT SET ON WINDOWS. Reading only `HOME` made every home-derived candidate in this
/// module resolve to `None` on the one platform whose driver resolution has repeatedly failed —
/// silently, because each caller treats `None` as "not present" rather than "could not look".
/// Windows exposes the home directory as `USERPROFILE` (and, on domain-joined machines, as
/// `HOMEDRIVE` + `HOMEPATH`), so fall through those before giving up.
fn dirs_home() -> Option<PathBuf> {
    if let Some(h) = std::env::var_os("HOME").filter(|v| !v.is_empty()) {
        return Some(PathBuf::from(h));
    }
    if let Some(h) = std::env::var_os("USERPROFILE").filter(|v| !v.is_empty()) {
        return Some(PathBuf::from(h));
    }
    match (std::env::var_os("HOMEDRIVE"), std::env::var_os("HOMEPATH")) {
        (Some(drive), Some(path)) if !drive.is_empty() && !path.is_empty() => {
            // `drive` is already an `OsString` from `var_os`; wrapping it in `OsString::from`
            // is a no-op that clippy rejects under -D warnings.
            let mut p = drive;
            p.push(path);
            Some(PathBuf::from(p))
        }
        _ => None,
    }
}

/// Check whether a usable Chromium binary already exists in known cache paths.
fn find_installed_browser() -> bool {
    for cache_dir in CACHE_DIRS {
        let base = expand_home(cache_dir);
        if !base.exists() {
            continue;
        }
        // Check for chromium-* directories (e.g. chromium-1148, chrome)
        for entry in std::fs::read_dir(&base).into_iter().flatten().flatten() {
            let name = entry.file_name();
            let name_str = name.to_string_lossy();
            for pattern in CHROMIUM_DIRS {
                if name_str.starts_with(pattern) && entry.path().is_dir() {
                    info!(path = %entry.path().display(), "Found installed browser");
                    return true;
                }
            }
        }
    }
    false
}

/// Ensure a Chromium browser is installed.
///
/// Locate patchright's bundled Playwright driver — returns `(node_exe, cli_js)`.
///
/// patchright is a stealth-patched Playwright fork. Driving ITS driver from
/// playwright-rs removes the vanilla `Runtime.enable` call, which is both the #1
/// anti-bot detection signature AND the source of the `Runtime.*`/console event
/// flood that makes per-action latency huge on heavy sites. patchright bundles
/// playwright-core 1.60 (the exact protocol playwright-rs 0.13 targets), so the
/// Rust bindings drive it unchanged — they just go through patchright's stealth
/// layer underneath.
///
/// Resolution, in order: `WRIT_PATCHRIGHT_DRIVER` (operator override → a `.../driver` dir),
/// `WRIT_BUNDLED_DRIVER` (what an installer shipped), a
/// `patchright-driver/` shipped NEXT TO the executable (or under `WRIT_HOME`) so a release needs no
/// Python at all, then `python3`/`python -c "import patchright"` to find an installed package, then
/// common site-packages globs. Returns `None` when nothing is found, so the caller transparently
/// falls back to the bundled vanilla driver.
pub fn find_patchright_driver() -> Option<(PathBuf, PathBuf)> {
    // 1/2/2b — the driver this app SHIPS. One resolver, shared with `runtime_setup` (see
    // [`bundled_driver_dir`]): the operator override, the shell's env var, and exe-relative
    // discovery all live there so the stealth driver, the runtime-status payload and the Chromium
    // installer can never again disagree about whether a bundled driver exists.
    if let Some(dir) = bundled_driver_dir() {
        if let Some(r) = driver_from_dir(&dir) {
            return Some(r);
        }
    }
    // Nothing bundled resolved. Say EXACTLY what was inspected before falling through to the Python
    // probes (which never succeed in a shipped app) and ultimately to the compile-time baked driver
    // path — a path on the CI machine that does not exist here, so the client sits waiting on a
    // driver that never handshakes and the whole thing surfaces as an opaque "Playwright timeout"
    // instead of "no driver". Twice now the resolution has been debugged by hand because the daemon
    // reported nothing; a shipped build has to be able to answer "where did you look?" from its log.
    {
        let exe = std::env::current_exe().ok();
        let tried: Vec<String> = bundled_engine_driver_candidates()
            .iter()
            .map(|p| p.display().to_string())
            .collect();
        tracing::warn!(
            current_exe = ?exe,
            writ_bundled_driver = ?std::env::var_os(ENV_BUNDLED_DRIVER),
            writ_patchright_driver = ?std::env::var_os(ENV_PATCHRIGHT_DRIVER),
            home = ?dirs_home(),
            candidates_tried = ?tried,
            "no BUNDLED patchright driver resolved next to the executable"
        );
    }
    // 3. A patchright driver that TRAVELS WITH the binary.
    //
    // Every probe below this point needs a Python interpreter that can `import patchright`. A
    // downloaded release binary / container image has no such interpreter, so a SHIPPED agent
    // always fell through to the vanilla driver — silently, since the fallback only logs a warning.
    // Vanilla leaves `Runtime.enable` on, which is an instant anti-bot tell, so the stealth path
    // existed but was dead in exactly the deployments that need it most. Probing a sibling
    // directory first lets the release drop the driver in with no Python anywhere in the image.
    for dir in sibling_patchright_candidates() {
        if let Some(r) = driver_from_dir(&dir) {
            return Some(r);
        }
    }
    // 4. Interpreters that can `import patchright`: the patchright CLI's OWN python
    //    (via its shebang — most reliable, it's by definition the env that has it),
    //    then python3 / python on PATH.
    let mut interps: Vec<String> = Vec::new();
    if let Some(py) = patchright_cli_python() {
        interps.push(py);
    }
    interps.push("python3".to_string());
    interps.push("python".to_string());
    for py in interps {
        if let Some(dir) = py_patchright_driver_dir(&py) {
            if let Some(r) = driver_from_dir(&dir) {
                return Some(r);
            }
        }
    }
    // 5. Glob common site-packages layouts (user-site + nearby venvs).
    for dir in candidate_patchright_dirs() {
        if let Some(r) = driver_from_dir(&dir) {
            return Some(r);
        }
    }
    None
}

/// Env var an OPERATOR sets to pin a specific patchright `.../driver` directory. Highest priority.
pub const ENV_PATCHRIGHT_DRIVER: &str = "WRIT_PATCHRIGHT_DRIVER";

/// Env var the Tauri shell sets to the driver dir (or its `node` exe) when the resource shipped.
/// Kept here rather than in `local::runtime_setup` because THIS module is feature-independent and
/// both consumers must agree on the spelling; `runtime_setup::ENV_BUNDLED_DRIVER` aliases it.
pub const ENV_BUNDLED_DRIVER: &str = "WRIT_BUNDLED_DRIVER";

/// **THE** resolver for the patchright driver directory this app ships. Returns a directory that is
/// already proven to hold a real driver (`node[.exe]` + `package/cli.js`), or `None`.
///
/// ## Why this is one function
/// The driver had FOUR independent consumers and they did not agree:
/// * [`find_patchright_driver`] — the stealth driver behind `PLAYWRIGHT_NODE_EXE` (had the
/// exe-relative fallback);
/// * `runtime_setup::detect_driver` — the `driver.bundled` field of `GET /v1/runtime/status`
/// (env var ONLY);
/// * `runtime_setup::resolve_install_command` — `node cli.js install chromium`, the only Chromium
/// installer a shipped app has once the direct download is unavailable (env var ONLY);
/// * the Tauri shell, which computes the path a fourth time from its own `resource_dir()`.
///
/// So on any install where the shell does not export `WRIT_BUNDLED_DRIVER` — a fresh Windows
/// install, a portable/unpacked build, a `.deb`/AppImage, or the daemon started by hand — the
/// stealth path recovered while the status reported `bundled: false` and the Chromium installer
/// reported "no Chromium installer found (bundled driver missing)", with the driver sitting in the
/// install tree the whole time. Setting the env var by hand fixed all three at once, which is
/// exactly why it looked like an env-var bug rather than three copies of one resolver.
///
/// SECURITY: the `node` under the returned directory is EXECUTED. Every candidate is anchored to an
/// operator-set env var or to the running executable's own directory — never the CWD, never remote
/// input — and [`driver_from_dir`] validates the layout before a directory can win.
pub fn bundled_driver_dir() -> Option<PathBuf> {
    // Explicit env first: an operator pin outranks discovery, and the shell's value (when it is set)
    // is the cheapest correct answer. Tolerate both shapes — the dir itself, or its `node` exe.
    for key in [ENV_PATCHRIGHT_DRIVER, ENV_BUNDLED_DRIVER] {
        let Some(raw) = std::env::var_os(key).filter(|v| !v.is_empty()) else {
            continue;
        };
        let p = PathBuf::from(raw);
        let dir = if p.is_dir() { p } else { p.parent().map(Path::to_path_buf).unwrap_or_default() };
        // Normalized before it escapes: `resolve_install_command` spawns `<dir>/node <dir>/package/
        // cli.js install chromium`, so a verbatim dir here is the same EISDIR death as the driver.
        let dir = simplified_path(&dir);
        if driver_from_dir(&dir).is_some() {
            return Some(dir);
        }
    }
    // Then find it ourselves, relative to `current_exe` — the path that needs no cooperation from
    // whatever launched us.
    //
    // MEMOIZED. This is reached from `runtime_setup::detect_driver`, which serves the POLLED
    // `GET /v1/runtime/status`, so an un-cached answer meant re-walking the install tree on every
    // poll — under Windows Defender, a repeated traversal of `C:\Program Files\...` is slow enough
    // to be felt as UI latency. The install tree cannot change under a running daemon (an update
    // replaces the files and restarts it), so resolving once per process is correct.
    static DISCOVERED: std::sync::OnceLock<Option<PathBuf>> = std::sync::OnceLock::new();
    DISCOVERED
        .get_or_init(|| {
            bundled_engine_driver_candidates().into_iter().find(|d| driver_from_dir(d).is_some())
        })
        .clone()
}

/// Directory name a PATCHRIGHT (stealth) driver shipped alongside the binary uses.
/// Kept next to [`SIBLING_DRIVER_DIRNAME`] because the same three things must agree on it: this
/// lookup, the release archive layout, and the container image. Deliberately a DIFFERENT directory
/// from the vanilla one so a release can carry both and the stealth driver is chosen on merit
/// rather than by overwriting.
pub const SIBLING_PATCHRIGHT_DIRNAME: &str = "patchright-driver";

/// Candidate directories for a bundled patchright driver, most specific first.
///
/// SECURITY: mirrors [`sibling_driver_candidates`] exactly — the resolved `node` is EXECUTED, so
/// every candidate is anchored to the running executable's own directory or `WRIT_HOME`, never to
/// the CWD and never to anything remote.
fn sibling_patchright_candidates() -> Vec<PathBuf> {
    let mut out = Vec::new();
    if let Ok(exe) = std::env::current_exe() {
        if let Some(dir) = exe.parent() {
            out.push(dir.join(SIBLING_PATCHRIGHT_DIRNAME));
        }
    }
    let writ_home = std::env::var("WRIT_HOME")
        .ok()
        .map(PathBuf::from)
        .or_else(|| dirs_home().map(|h| h.join(".writ")));
    if let Some(home) = writ_home {
        out.push(home.join(SIBLING_PATCHRIGHT_DIRNAME));
    }
    out
}

/// Driver dirs shipped by the TAURI DESKTOP bundle, resolved RELATIVE TO THE DAEMON'S OWN EXE — the
/// self-sufficient path that does NOT depend on the shell exporting `WRIT_BUNDLED_DRIVER`.
///
/// Tauri copies the resource `resources/engine/<triple>/driver` into the install tree next to the
/// executable (`<install>/resources/engine/<triple>/driver` on Windows/Linux; inside
/// `Contents/Resources/` on macOS, one level up from the sidecar in `Contents/MacOS/`). We probe both
/// shapes under the exe's directory, matching a flat `.../engine/driver` and any per-triple
/// `.../engine/<name>/driver`, and let [`driver_from_dir`] validate that a real `node[.exe]` +
/// `package/cli.js` are present. Order is candidates only; the caller validates.
fn bundled_engine_driver_candidates() -> Vec<PathBuf> {
    match std::env::current_exe().ok().and_then(|e| e.parent().map(Path::to_path_buf)) {
        Some(base) => bundled_engine_driver_candidates_in(&base),
        None => Vec::new(),
    }
}

/// [`bundled_engine_driver_candidates`] for an explicit exe directory (the testable core).
///
/// Deliberately LAYOUT-INDEPENDENT. The first cut hard-coded `resources/engine/{,<triple>/}driver`,
/// which is what the bundle config declares — but a hard-coded guess is exactly what already failed
/// once here, and Tauri's installed layout differs per platform (and per installer: NSIS vs MSI vs
/// the macOS `.app`). So we do what a human does when the guess misses: walk down from the install
/// root looking for a real driver. Bounded depth + a pruned walk keep it cheap, and
/// [`driver_from_dir`] is still the thing that decides a hit (node[.exe] + package/cli.js present),
/// so a same-named-but-empty directory can never win.
fn bundled_engine_driver_candidates_in(base: &Path) -> Vec<PathBuf> {
    let mut out = Vec::new();
    // Fast paths first, so the common layouts cost one `is_dir` each and never touch the walk.
    // macOS: the sidecar lives in Contents/MacOS while resources are in Contents/Resources.
    for root in [base.to_path_buf(), base.join("..").join("Resources")] {
        let engine = root.join("resources").join("engine");
        if engine.is_dir() {
            out.push(engine.join("driver"));
            if let Ok(entries) = std::fs::read_dir(&engine) {
                for entry in entries.flatten() {
                    if entry.path().is_dir() {
                        out.push(entry.path().join("driver"));
                    }
                }
            }
        }
    }
    // A known layout already holds a REAL driver ⇒ stop. The walk below is a RECOVERY path for
    // layouts we don't know; running it anyway made the common case pay a full traversal of the
    // install tree for nothing.
    if out.iter().any(|d| driver_from_dir(d).is_some()) {
        return out;
    }
    // Bounded discovery walk: any `*/driver` under the install root, depth-limited so a deep tree
    // (or a symlink loop) can't turn startup into a filesystem crawl. Depth 6 (not 4): the known
    // Tauri layout puts it at depth 4 (`resources/engine/<triple>/driver`), and guessing the
    // installer's exact nesting is precisely what has already failed twice here — the extra levels
    // cost one `read_dir` each on a pruned tree and remove a whole class of near-miss.
    collect_driver_dirs(base, 6, &mut out);
    out.dedup();
    out
}

/// Depth-bounded scan for directories NAMED `driver` under `dir`, appending each to `out`.
/// Skips the browser payload (`chrome-*`) — it is large, never contains the node driver, and is the
/// one subtree that would dominate the walk.
fn collect_driver_dirs(dir: &Path, depth_left: usize, out: &mut Vec<PathBuf>) {
    if depth_left == 0 {
        return;
    }
    let Ok(entries) = std::fs::read_dir(dir) else {
        return;
    };
    for entry in entries.flatten() {
        let p = entry.path();
        // `file_type` here does NOT follow symlinks, so a link loop cannot trap the walk.
        if !entry.file_type().map(|t| t.is_dir()).unwrap_or(false) {
            continue;
        }
        let name = entry.file_name();
        let name = name.to_string_lossy();
        if name.starts_with("chrome-") || name == "node_modules" {
            continue;
        }
        if name == "driver" {
            out.push(p.clone());
        }
        collect_driver_dirs(&p, depth_left - 1, out);
    }
}

/// Directory name a driver shipped **alongside** the binary is expected to use.
/// Kept in one place because three things must agree on it: this lookup, the release archive
/// layout (`.github/workflows/release.yml`), and the container image (`Dockerfile`).
pub const SIBLING_DRIVER_DIRNAME: &str = "playwright-driver";

/// Locate a vanilla Playwright driver that TRAVELS WITH the binary.
///
/// `vendor/playwright-rs`'s build script bakes an **absolute** path to whatever driver it used —
/// either the build's `OUT_DIR` or the builder's `~/.cache/playwright-rs-driver/…`. Both are paths
/// on the machine that *compiled* the binary. The vendored resolver checks that path with
/// `.exists()`, so on any other machine it simply misses, and the only remaining fallbacks are an
/// `npm` Playwright on `PATH` or the `playwright-rs install` user cache — neither of which someone
/// who downloaded a release binary (or pulled the container image) has. The failure surfaces late,
/// as `ServerNotFound` on the first browser launch, long after startup looked healthy.
///
/// So probe for a driver directory shipped next to the executable — the layout the release archives
/// and the container image use — and then under `WRIT_HOME`, so an operator can drop one in without
/// repackaging. Returns `(node, cli.js)`, or `None` when nothing usable is present.
pub fn find_sibling_driver() -> Option<(PathBuf, PathBuf)> {
    for dir in sibling_driver_candidates() {
        if let Some(r) = driver_from_dir(&dir) {
            return Some(r);
        }
    }
    None
}

/// Candidate directories for [`find_sibling_driver`], most specific first.
///
/// SECURITY: the resolved `node` is later EXECUTED, so every candidate is anchored to a path the
/// operator controls — the directory the running executable was launched from, or `WRIT_HOME`.
/// Nothing here is derived from the current working directory or from any remote input.
fn sibling_driver_candidates() -> Vec<PathBuf> {
    let mut out = Vec::new();
    if let Ok(exe) = std::env::current_exe() {
        if let Some(dir) = exe.parent() {
            out.push(dir.join(SIBLING_DRIVER_DIRNAME));
        }
    }
    let writ_home = std::env::var("WRIT_HOME")
        .ok()
        .map(PathBuf::from)
        .or_else(|| dirs_home().map(|h| h.join(".writ")));
    if let Some(home) = writ_home {
        out.push(home.join(SIBLING_DRIVER_DIRNAME));
    }
    out
}

/// Strip a Windows **verbatim** (`\\?\`) prefix when it is safe to do so.
///
/// NODE CANNOT RUN A SCRIPT WHOSE PATH IS VERBATIM. `node \\?\C:\…\cli.js` dies before executing
/// a single line:
/// ```text
/// Error: EISDIR: illegal operation on a directory, lstat 'C:'
/// at Object.realpathSync (node:fs)
/// at resolveMainPath (node:internal/modules/run_main)
/// ```
/// `resolveMainPath` → `toRealPath` → `realpathSync` walks the path component by component; against
/// `\\?\C:\…` it ends up calling `lstat("C:")`, which is a directory reference, not a file — EISDIR,
/// exit code 1. The driver then dies ~200 ms in, and because the only liveness check ran at 100 ms
/// the caller saw nothing but "Playwright initialization timeout after 30 seconds".
///
/// Where the prefix comes from: the Tauri shell derives the resource dir from `resource_dir()` and
/// exports it as `WRIT_BUNDLED_DRIVER`, and on Windows that value carries `\\?\`. Nothing on the
/// Rust side minds — `exists()`, `join()` and `CreateProcess` all accept it — so it survives every
/// check we make and only detonates inside Node.
///
/// Only `\\?\C:\…` and `\\?\UNC\server\share\…` are simplified (the two forms with a plain
/// equivalent), and only when the result stays under Windows' legacy `MAX_PATH`: past that the
/// verbatim form is load-bearing and removing it would break the path instead. `\\.\` device paths
/// and bare `\\?\` verbatim paths are returned untouched. No-op on every other platform.
pub fn simplified_path(p: &Path) -> PathBuf {
    #[cfg(not(windows))]
    {
        p.to_path_buf()
    }
    #[cfg(windows)]
    {
        use std::ffi::OsString;
        use std::path::{Component, Prefix};

        let mut comps = p.components();
        let Some(Component::Prefix(prefix)) = comps.next() else {
            return p.to_path_buf();
        };
        let rest = comps.as_path();
        let simplified = match prefix.kind() {
            Prefix::VerbatimDisk(drive) => {
                let mut s = OsString::from(format!("{}:", drive as char));
                if rest.as_os_str().is_empty() {
                    s.push("\\");
                } else {
                    s.push(rest.as_os_str());
                }
                PathBuf::from(s)
            }
            Prefix::VerbatimUNC(server, share) => {
                let mut s = OsString::from(r"\\");
                s.push(server);
                s.push("\\");
                s.push(share);
                s.push(rest.as_os_str());
                PathBuf::from(s)
            }
            // Verbatim(..) / DeviceNS(..) have no plain equivalent; Disk/UNC are already plain.
            _ => return p.to_path_buf(),
        };
        // Past MAX_PATH the `\\?\` prefix is what makes the path usable at all — keep it.
        if simplified.as_os_str().len() < 260 {
            simplified
        } else {
            p.to_path_buf()
        }
    }
}

/// Validate a patchright `driver` dir, returning `(node, cli.js)` if both exist.
///
/// THE choke point every driver resolution funnels through, and therefore the right place to
/// normalize: both paths are handed to Node (one as the program, one as its main module), so a
/// verbatim prefix here is fatal — see [`simplified_path`].
fn driver_from_dir(dir: &Path) -> Option<(PathBuf, PathBuf)> {
    let dir = simplified_path(dir);
    let node = if cfg!(windows) {
        dir.join("node.exe")
    } else {
        dir.join("node")
    };
    let cli = dir.join("package").join("cli.js");
    if node.exists() && cli.exists() {
        Some((node, cli))
    } else {
        None
    }
}

/// Run `<py> -c "import patchright"` and return its bundled `driver` dir.
fn py_patchright_driver_dir(py: &str) -> Option<PathBuf> {
    let out = std::process::Command::new(py)
        .args([
            "-c",
            "import patchright,os;print(os.path.join(os.path.dirname(patchright.__file__),'driver'),end='')",
        ])
        .output()
        .ok()?;
    if !out.status.success() {
        return None;
    }
    let p = PathBuf::from(String::from_utf8_lossy(&out.stdout).trim().to_string());
    if p.is_dir() {
        Some(p)
    } else {
        None
    }
}

/// The interpreter that backs the `patchright` CLI (read from its shebang), so we
/// import from the exact env that installed patchright even when it's a venv not
/// otherwise on PATH for `python3`.
fn patchright_cli_python() -> Option<String> {
    let out = std::process::Command::new("which").arg("patchright").output().ok()?;
    if !out.status.success() {
        return None;
    }
    let cli = String::from_utf8_lossy(&out.stdout).trim().to_string();
    if cli.is_empty() {
        return None;
    }
    // SECURITY: `which` follows $PATH, which an attacker who controls the launch
    // environment can poison. We read the CLI's shebang and later EXECUTE that
    // interpreter, so only trust a CLI resolved from an operator-controlled root
    // (HOME or WRIT_HOME) — never a cwd-relative or otherwise-attacker-placed path.
    let cli_path = std::fs::canonicalize(&cli).ok()?;
    if !path_under_trusted_root(&cli_path) {
        warn!(cli = %cli_path.display(), "ignoring `patchright` from an untrusted PATH location");
        return None;
    }
    let first = std::fs::read_to_string(&cli_path).ok()?;
    first.lines().next()?.strip_prefix("#!").map(|s| s.trim().to_string())
}

/// True if `p` lives under an operator-controlled root we're willing to execute
/// code from (HOME, WRIT_HOME). Paths must be canonicalized before this check so
/// `..` traversal can't escape the trusted prefix.
fn path_under_trusted_root(p: &Path) -> bool {
    let mut roots: Vec<PathBuf> = Vec::new();
    if let Ok(home) = std::env::var("HOME") {
        roots.push(PathBuf::from(home));
    }
    if let Ok(writ_home) = std::env::var("WRIT_HOME") {
        roots.push(PathBuf::from(writ_home));
    }
    roots
        .iter()
        .filter_map(|r| std::fs::canonicalize(r).ok())
        .any(|root| p.starts_with(&root))
}

/// Common site-packages locations to probe for `patchright/driver` when no
/// interpreter on PATH can import it (user-site installs, project venvs).
fn candidate_patchright_dirs() -> Vec<PathBuf> {
    const TAIL: &str = "site-packages/patchright/driver";
    let mut out = Vec::new();
    // For each child of `base` whose name starts with `prefix`, push child/<sub>.
    let glob = |out: &mut Vec<PathBuf>, base: PathBuf, prefix: &str, sub: &str| {
        if let Ok(rd) = std::fs::read_dir(&base) {
            for e in rd.flatten() {
                if e.file_name().to_string_lossy().starts_with(prefix) {
                    out.push(e.path().join(sub));
                }
            }
        }
    };
    if let Ok(home) = std::env::var("HOME") {
        let home = PathBuf::from(home);
        // macOS user-site: ~/Library/Python/<ver>/lib/python/site-packages/...
        glob(&mut out, home.join("Library/Python"), "", &format!("lib/python/{TAIL}"));
        // Linux user-site: ~/.local/lib/python<ver>/site-packages/...
        glob(&mut out, home.join(".local/lib"), "python", TAIL);
    }
    // A venv under WRIT_HOME (operator-controlled), if one exists. SECURITY: never
    // probe cwd-relative `./.venv` / `./*/.venv` — the daemon may be launched from
    // an attacker-controlled directory, and we later EXECUTE the resolved node/cli.js.
    // Driver dirs must come only from trusted, operator-controlled roots.
    if let Ok(writ_home) = std::env::var("WRIT_HOME") {
        glob(&mut out, PathBuf::from(writ_home).join(".venv/lib"), "python", TAIL);
    }
    out
}

/// Decide the browser DRIVER before launch.
///
/// If patchright's stealth driver is already present, there's nothing to do —
/// `BrowserManager::initialize()` will pick it up. If it's NOT present and we're
/// on an interactive terminal, ask the user to choose: install patchright
/// (stealth, recommended) or continue with regular Playwright (more easily
/// flagged by anti-bot + slower on heavy pages). Non-interactive runs
/// (service/daemon) are never blocked — they warn and continue on the bundled
/// vanilla driver, overridable via `patchright install` / `WRIT_PATCHRIGHT_DRIVER`.
pub async fn ensure_stealth_driver() {
    if find_patchright_driver().is_some() {
        info!("patchright stealth driver detected — anti-bot stealth enabled");
        return;
    }

    use std::io::{IsTerminal, Write};

    if !std::io::stdin().is_terminal() {
        warn!(
            "patchright (stealth) driver not found — using regular Playwright, which is \
             more easily detected by anti-bot systems and slower on heavy pages. Install \
             patchright or set WRIT_PATCHRIGHT_DRIVER to enable stealth."
        );
        return;
    }

    println!();
    println!("  \x1b[33m⚠  Stealth driver (patchright) not found.\x1b[0m");
    println!("     Regular Playwright is easily flagged by anti-bot systems (Cloudflare,");
    println!("     DataDome, …) and is slower to react on heavy pages.");
    println!();
    println!("     [1] Install patchright now  \x1b[2m(recommended — enables stealth)\x1b[0m");
    println!("     [2] Continue with regular Playwright");
    print!("  Choose [1/2] (default 1): ");
    let _ = std::io::stdout().flush();

    let mut input = String::new();
    let _ = std::io::stdin().read_line(&mut input);

    if input.trim() == "2" {
        warn!("Continuing with regular (non-stealth) Playwright by user choice.");
        return;
    }

    // default / "1" → best-effort install of the patchright package (which ships
    // the stealth driver). The browser binary is handled by ensure_browser_installed
    // / the chrome channel, so we only need the package here.
    println!("  Installing patchright …");
    let installed = try_install_command("python3", &["-m", "pip", "install", "--upgrade", "patchright"])
        .await
        .unwrap_or(false);

    if installed && find_patchright_driver().is_some() {
        println!("  \x1b[32m✓ patchright installed — stealth enabled.\x1b[0m");
    } else {
        warn!(
            "Could not auto-install patchright — continuing with regular Playwright. \
             Install it manually with:  python3 -m pip install patchright  (or point \
             WRIT_PATCHRIGHT_DRIVER at an existing patchright driver dir)."
        );
    }
}

/// First checks well-known cache directories. If no browser is found, attempts
/// to install via `patchright install chromium` (preferred) then falls back to
/// `playwright install chromium`. Returns `true` when a browser is available
/// after the call.
pub async fn ensure_browser_installed() -> Result<bool> {
    if find_installed_browser() {
        info!("Browser already installed");
        return Ok(true);
    }

    warn!("No installed browser found — attempting install");

    // Try patchright first (stealth-patched Chromium)
    if try_install_command("patchright", &["install", "chromium"]).await? {
        info!("Installed Chromium via patchright");
        return Ok(true);
    }

    // Fall back to playwright
    if try_install_command("playwright", &["install", "chromium"]).await? {
        info!("Installed Chromium via playwright");
        return Ok(true);
    }

    // Try npx variants
    if try_install_command("npx", &["patchright", "install", "chromium"]).await? {
        info!("Installed Chromium via npx patchright");
        return Ok(true);
    }

    anyhow::bail!("Failed to install Chromium via any known method")
}

/// Run an install command with a 300-second timeout. Returns `true` on success.
async fn try_install_command(program: &str, args: &[&str]) -> Result<bool> {
    info!(cmd = program, ?args, "Running install command");

    let result = tokio::time::timeout(
        std::time::Duration::from_secs(300),
        tokio::process::Command::new(program)
            .args(args)
            .stdout(std::process::Stdio::piped())
            .stderr(std::process::Stdio::piped())
            .spawn()
            .context(format!("Failed to spawn {program}"))?
            .wait_with_output(),
    )
    .await;

    match result {
        Ok(Ok(output)) => {
            if output.status.success() {
                Ok(true)
            } else {
                let stderr = String::from_utf8_lossy(&output.stderr);
                warn!(cmd = program, %stderr, "Install command failed");
                Ok(false)
            }
        }
        Ok(Err(e)) => {
            warn!(cmd = program, error = %e, "Install command error");
            Ok(false)
        }
        Err(_) => {
            warn!(cmd = program, "Install command timed out after 300s");
            Ok(false)
        }
    }
}

#[cfg(test)]
mod tests {
    // NOTE: `use super::*` already lives further down in this module — do not re-import it here.

    /// The Tauri desktop layout `<install>/resources/engine/<triple>/driver` must resolve from the
    /// exe directory alone — the fresh-install case where the shell never set `WRIT_BUNDLED_DRIVER`.
    #[test]
    fn finds_the_bundled_driver_relative_to_the_exe() {
        let dir = tempfile::tempdir().unwrap();
        let base = dir.path();
        // Build a realistic per-triple bundle: .../resources/engine/x86_64-pc-windows-msvc/driver
        let driver = base
            .join("resources")
            .join("engine")
            .join("x86_64-pc-windows-msvc")
            .join("driver");
        std::fs::create_dir_all(driver.join("package")).unwrap();
        let node_name = if cfg!(windows) { "node.exe" } else { "node" };
        std::fs::write(driver.join(node_name), b"").unwrap();
        std::fs::write(driver.join("package").join("cli.js"), b"").unwrap();

        // The candidate list must include the real driver dir, and driver_from_dir must validate it.
        let cands = bundled_engine_driver_candidates_in(base);
        assert!(cands.contains(&driver), "per-triple driver not among candidates: {cands:?}");
        let resolved = cands.iter().find_map(|d| driver_from_dir(d));
        let (node, cli) = resolved.expect("a bundled driver should resolve");
        assert_eq!(node, driver.join(node_name));
        assert_eq!(cli, driver.join("package").join("cli.js"));

        // Nothing to find under an empty tree → empty candidate list, no panic.
        let empty = tempfile::tempdir().unwrap();
        assert!(bundled_engine_driver_candidates_in(empty.path()).is_empty());
    }

    /// The resolver must NOT depend on the exact bundle layout: a driver parked somewhere the
    /// hard-coded `resources/engine/...` guess doesn't cover must still be found. This is the case
    /// that made a fresh Windows install fail while a manual `WRIT_BUNDLED_DRIVER` worked.
    #[test]
    fn finds_the_driver_even_under_an_unexpected_layout() {
        let dir = tempfile::tempdir().unwrap();
        let base = dir.path();
        // A layout NOT matching resources/engine/<triple>/driver.
        let driver = base.join("engine").join("win-x64").join("driver");
        std::fs::create_dir_all(driver.join("package")).unwrap();
        let node_name = if cfg!(windows) { "node.exe" } else { "node" };
        std::fs::write(driver.join(node_name), b"").unwrap();
        std::fs::write(driver.join("package").join("cli.js"), b"").unwrap();

        let resolved = bundled_engine_driver_candidates_in(base)
            .iter()
            .find_map(|d| driver_from_dir(d));
        assert!(resolved.is_some(), "an off-layout driver must still resolve");

        // A directory NAMED `driver` but missing node/cli.js must NOT be accepted as a hit.
        let decoy = tempfile::tempdir().unwrap();
        std::fs::create_dir_all(decoy.path().join("stuff").join("driver")).unwrap();
        assert!(
            bundled_engine_driver_candidates_in(decoy.path())
                .iter()
                .find_map(|d| driver_from_dir(d))
                .is_none(),
            "an empty `driver` dir must not resolve"
        );
    }

    /// [`bundled_driver_dir`] is the ONE resolver three consumers share, so pin its contract:
    /// a real layout behind the env var wins, an env var pointing at a non-driver is not a hit
    /// (it must fall through rather than pin a directory nothing can launch), and the `node` exe
    /// form is accepted as well as the directory form.
    #[test]
    fn bundled_driver_dir_validates_the_layout_behind_the_env_var() {
        let _lock = env_lock();
        #[cfg(feature = "local")]
        let _g = crate::local::config::test_env_guard();

        let prev_bundled = std::env::var_os(ENV_BUNDLED_DRIVER);
        let prev_pin = std::env::var_os(ENV_PATCHRIGHT_DRIVER);
        std::env::remove_var(ENV_PATCHRIGHT_DRIVER);

        let tmp = std::env::temp_dir().join(format!("writ_bundled_driver_{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&tmp);
        let driver = tmp.join("driver");
        std::fs::create_dir_all(driver.join("package")).unwrap();
        let node_name = if cfg!(windows) { "node.exe" } else { "node" };
        std::fs::write(driver.join(node_name), b"").unwrap();
        std::fs::write(driver.join("package").join("cli.js"), b"").unwrap();

        // Directory form.
        std::env::set_var(ENV_BUNDLED_DRIVER, &driver);
        assert_eq!(bundled_driver_dir().as_deref(), Some(driver.as_path()));

        // `node` exe form — the shell may export either.
        std::env::set_var(ENV_BUNDLED_DRIVER, driver.join(node_name));
        assert_eq!(bundled_driver_dir().as_deref(), Some(driver.as_path()));

        // An env var pointing at a directory that is NOT a driver must not be accepted. It falls
        // through to exe-relative discovery, which finds nothing beside the test binary — the point
        // is that a bogus env value can never "win" and mask a real driver elsewhere.
        let bogus = tmp.join("not-a-driver");
        std::fs::create_dir_all(&bogus).unwrap();
        std::env::set_var(ENV_BUNDLED_DRIVER, &bogus);
        assert_ne!(bundled_driver_dir().as_deref(), Some(bogus.as_path()));

        match prev_bundled {
            Some(v) => std::env::set_var(ENV_BUNDLED_DRIVER, v),
            None => std::env::remove_var(ENV_BUNDLED_DRIVER),
        }
        if let Some(v) = prev_pin {
            std::env::set_var(ENV_PATCHRIGHT_DRIVER, v);
        }
        let _ = std::fs::remove_dir_all(&tmp);
    }

    /// A verbatim `\\?\` path handed to Node kills it before it runs a line
    /// (`EISDIR: … lstat 'C:'` from `resolveMainPath`). Pin the simplification, and pin that the
    /// forms with no plain equivalent are left alone.
    #[test]
    fn verbatim_windows_prefixes_are_simplified() {
        // Non-verbatim paths are returned untouched on every platform.
        let plain = PathBuf::from("relative/driver");
        assert_eq!(simplified_path(&plain), plain);

        #[cfg(windows)]
        {
            assert_eq!(
                simplified_path(Path::new(r"\\?\C:\Program Files\Writ\driver\node.exe")),
                PathBuf::from(r"C:\Program Files\Writ\driver\node.exe")
            );
            assert_eq!(simplified_path(Path::new(r"\\?\C:\")), PathBuf::from(r"C:\"));
            assert_eq!(
                simplified_path(Path::new(r"\\?\UNC\server\share\driver")),
                PathBuf::from(r"\\server\share\driver")
            );
            // Already plain → unchanged.
            let plain_disk = PathBuf::from(r"C:\Program Files\Writ\driver");
            assert_eq!(simplified_path(&plain_disk), plain_disk);
            // Device namespace has no plain equivalent → untouched.
            let device = PathBuf::from(r"\\.\pipe\something");
            assert_eq!(simplified_path(&device), device);
            // Past MAX_PATH the prefix is load-bearing → kept.
            let long = PathBuf::from(format!(r"\\?\C:\{}", "a".repeat(300)));
            assert_eq!(simplified_path(&long), long);
        }
    }

    /// `HOME` is not set on Windows — every home-derived driver candidate resolved to `None` there.
    /// `USERPROFILE` must stand in for it.
    #[test]
    fn home_falls_back_to_userprofile_when_home_is_unset() {
        let _lock = env_lock();
        #[cfg(feature = "local")]
        let _g = crate::local::config::test_env_guard();

        let prev_home = std::env::var_os("HOME");
        let prev_profile = std::env::var_os("USERPROFILE");

        std::env::remove_var("HOME");
        std::env::set_var("USERPROFILE", "/writ-test/userprofile");
        assert_eq!(dirs_home(), Some(PathBuf::from("/writ-test/userprofile")));

        // HOME still wins when both are present (unix behaviour is unchanged).
        std::env::set_var("HOME", "/writ-test/home");
        assert_eq!(dirs_home(), Some(PathBuf::from("/writ-test/home")));

        match prev_home {
            Some(v) => std::env::set_var("HOME", v),
            None => std::env::remove_var("HOME"),
        }
        match prev_profile {
            Some(v) => std::env::set_var("USERPROFILE", v),
            None => std::env::remove_var("USERPROFILE"),
        }
    }

    /// Serializes every env-mutating test in this module.
    ///
    /// `local::config::test_env_guard` is gated behind the `local` feature, which is NOT in
    /// `default` — so under a plain `cargo test` it compiled to nothing and these tests raced each
    /// other on `HOME`/`WRIT_HOME` (process-global). The symptom was a failing assertion in a test
    /// that had not changed, which reads like a real regression rather than a flake. This lock is
    /// unconditional, so it holds for every feature combination.
    static ENV_LOCK: std::sync::Mutex<()> = std::sync::Mutex::new(());
    fn env_lock() -> std::sync::MutexGuard<'static, ()> {
        // Do not let one panicking test poison the rest of the module.
        ENV_LOCK.lock().unwrap_or_else(|e| e.into_inner())
    }

    use super::*;

    #[test]
    fn trusted_root_rejects_paths_outside_writ_home() {
        // Serialize with every other test that mutates the process-global HOME/WRIT_HOME env — this
        // test both overrides WRIT_HOME and REMOVES HOME, which would otherwise race a concurrent
        // test's `Paths::resolve()` (e.g. the backup snapshot opening the wrong keyed DB). The shared
        // guard lives in `local::config`; the WRIT_HOME-based tests it serializes with only exist in
        // the `local` build, so the guard is only needed there.
        let _lock = env_lock();
        #[cfg(feature = "local")]
        let _g = crate::local::config::test_env_guard();
        // A poisoned $PATH could resolve `patchright` anywhere; only paths under a
        // canonicalized operator root must be trusted.
        let tmp = std::env::temp_dir().join(format!("writ_trust_test_{}", std::process::id()));
        let inside = tmp.join("bin").join("patchright");
        std::fs::create_dir_all(inside.parent().unwrap()).unwrap();
        std::fs::write(&inside, b"#!/usr/bin/python3\n").unwrap();

        // Preserve and override the env for a deterministic check. The guards taken at the top of
        // this test are what make "preserve and restore" deterministic: HOME/WRIT_HOME are
        // process-global, so without them a sibling test mutating them on another thread lands
        // mid-assertion. They are NOT re-acquired here — `std::sync::Mutex` is not reentrant, and a
        // second `env_lock()` on this thread deadlocks against the guard still held above (shadowing
        // a `let _lock` does not drop the previous one; it lives until end of scope).
        let prev_home = std::env::var("HOME").ok();
        let prev_writ = std::env::var("WRIT_HOME").ok();
        std::env::set_var("WRIT_HOME", &tmp);
        std::env::remove_var("HOME");

        let inside_c = std::fs::canonicalize(&inside).unwrap();
        assert!(path_under_trusted_root(&inside_c), "path under WRIT_HOME must be trusted");

        // A world-writable path outside any trusted root must be rejected.
        let outside = std::fs::canonicalize(std::env::temp_dir()).unwrap();
        assert!(!path_under_trusted_root(&outside), "path outside trusted roots must be rejected");

        // Restore.
        match prev_home {
            Some(v) => std::env::set_var("HOME", v),
            None => std::env::remove_var("HOME"),
        }
        match prev_writ {
            Some(v) => std::env::set_var("WRIT_HOME", v),
            None => std::env::remove_var("WRIT_HOME"),
        }
        let _ = std::fs::remove_dir_all(&tmp);
    }

    /// The release archives and the container image both lay the driver out as
    /// `<exe dir>/playwright-driver`, and a binary that cannot find it starts, connects and reports
    /// healthy before failing every run at browser launch — a failure mode no smoke test catches.
    /// Pin the two things that make that layout work: the directory NAME, and the fact that
    /// `WRIT_HOME` is the documented second place to drop one.
    #[test]
    fn sibling_driver_is_found_next_to_the_executable_and_under_writ_home() {
        let _lock = env_lock();
        #[cfg(feature = "local")]
        let _g = crate::local::config::test_env_guard();

        let tmp = std::env::temp_dir().join(format!("writ_sibling_driver_{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&tmp);

        // A directory is only a driver once BOTH files are there — a half-extracted archive must
        // not be accepted, or the failure moves to `node` exiting with a parse error.
        let dir = tmp.join(SIBLING_DRIVER_DIRNAME);
        std::fs::create_dir_all(dir.join("package")).unwrap();
        assert!(driver_from_dir(&dir).is_none(), "empty dir must not pass as a driver");
        let node_name = if cfg!(windows) { "node.exe" } else { "node" };
        std::fs::write(dir.join(node_name), b"").unwrap();
        assert!(driver_from_dir(&dir).is_none(), "node without cli.js must not pass");
        std::fs::write(dir.join("package").join("cli.js"), b"").unwrap();
        let (node, cli) = driver_from_dir(&dir).expect("node + cli.js is a driver");
        assert_eq!(node, dir.join(node_name));
        assert_eq!(cli, dir.join("package").join("cli.js"));

        // `WRIT_HOME/playwright-driver` must be among the probed candidates.
        let prev_writ = std::env::var("WRIT_HOME").ok();
        std::env::set_var("WRIT_HOME", &tmp);
        assert!(
            sibling_driver_candidates().contains(&dir),
            "WRIT_HOME/{SIBLING_DRIVER_DIRNAME} must be a candidate, got {:?}",
            sibling_driver_candidates()
        );
        assert_eq!(
            find_sibling_driver().map(|(n, _)| n),
            Some(dir.join(node_name)),
            "a driver under WRIT_HOME must resolve"
        );

        // The executable's own directory is the FIRST candidate — that is the release-archive and
        // container layout, and it must not be reachable only through WRIT_HOME.
        let exe_dir = std::env::current_exe().ok().and_then(|e| e.parent().map(|p| p.to_path_buf()));
        if let Some(exe_dir) = exe_dir {
            assert_eq!(
                sibling_driver_candidates().first(),
                Some(&exe_dir.join(SIBLING_DRIVER_DIRNAME)),
                "the executable's directory must be probed first"
            );
        }

        match prev_writ {
            Some(v) => std::env::set_var("WRIT_HOME", v),
            None => std::env::remove_var("WRIT_HOME"),
        }
        let _ = std::fs::remove_dir_all(&tmp);
    }

    /// A release ships the stealth driver next to the binary; no Python is involved. This pins the
    /// directory name the release archive must use — if it drifts, a shipped agent silently falls
    /// back to the vanilla driver (Runtime.enable on = detectable), which is exactly the failure
    /// this lookup was added to end.
    #[test]
    fn sibling_patchright_dir_is_probed_from_writ_home() {
        // `WRIT_HOME` is process-global and several tests in this file drive it. Without the shared
        // guard this races them (they run on parallel threads), which is exactly how it first went
        // red — a flake, not a real failure, and the worst kind to leave behind.
        let _lock = env_lock();
        #[cfg(feature = "local")]
        let _g = crate::local::config::test_env_guard();

        let tmp = std::env::temp_dir().join(format!("writ-pr-{}", std::process::id()));
        let dir = tmp.join(SIBLING_PATCHRIGHT_DIRNAME);
        std::fs::create_dir_all(dir.join("package")).unwrap();
        let node = dir.join(if cfg!(windows) { "node.exe" } else { "node" });
        std::fs::write(&node, b"").unwrap();
        std::fs::write(dir.join("package").join("cli.js"), b"").unwrap();

        // SAFETY: single-threaded test process; restored immediately below.
        let prev = std::env::var_os("WRIT_HOME");
        std::env::set_var("WRIT_HOME", &tmp);
        let found = sibling_patchright_candidates()
            .into_iter()
            .find_map(|d| driver_from_dir(&d));
        match prev {
            Some(v) => std::env::set_var("WRIT_HOME", v),
            None => std::env::remove_var("WRIT_HOME"),
        }
        std::fs::remove_dir_all(&tmp).ok();

        let (n, c) = found.expect("a patchright driver under WRIT_HOME must be found");
        assert_eq!(n, node);
        assert!(c.ends_with("package/cli.js") || c.ends_with("package\\cli.js"));
    }

    /// The stealth and vanilla sibling directories must stay DISTINCT, so a release can carry both
    /// and the stealth one wins on merit instead of one silently overwriting the other.
    #[test]
    fn sibling_driver_dirnames_are_distinct() {
        assert_ne!(SIBLING_PATCHRIGHT_DIRNAME, SIBLING_DRIVER_DIRNAME);
    }
}

//! Local OAuth 2.1 authorization server — for MCP-capable AI apps that only speak OAuth.
//!
//! Several MCP hosts (and OpenAI-compat "custom connector" UIs) have NO api-key field: they run the
//! spec discovery dance instead. This module makes the daemon its own tiny authorization server so
//! those clients can mint a scoped local bearer without the user ever copying a key:
//!
//!   GET  /.well-known/oauth-protected-resource[/mcp] — RFC 9728: which AS protects this resource
//!   GET  /.well-known/oauth-authorization-server[/mcp] — RFC 8414: AS endpoints + capabilities
//!   POST /oauth/register  — RFC 7591 dynamic client registration (public clients, NO secret)
//!   GET  /oauth/authorize — authorization-code + PKCE (S256 ONLY); renders a local consent page
//!   POST /oauth/consent   — the consent form target (same-origin; loopback guard applies)
//!   POST /oauth/token     — code + refresh grants; mints `wlo_` access / `wrt_` refresh tokens
//!
//! Security model: everything is loopback (or the user's explicit LAN exposure) and the flow ends
//! in a USER CLICK on the consent page — same trust boundary as the 0600 runtime descriptor (any
//! same-user process could read that instead; OAuth here is about CLIENT UX, not new privilege).
//! Tokens are hash-stored (sha256, like `wlk_`), scope-gated through the same `auth::Scope` chain
//! (granted scope: `run`), expiring, and refresh-rotated. These routes are BEARER-EXEMPT in
//! `server::auth_mw` (they exist to mint the bearer) but stay behind the Origin/Host DNS-rebind
//! guard. NEVER log a raw code/token.

use crate::local::auth;
use crate::local::config::LocalConfig;
use crate::local::error::LocalResult;
use crate::local::server::AppState;
use crate::local::store::oauth as store;
use axum::extract::{Host, Query, State};
use axum::http::{header, StatusCode};
use axum::response::{Html, IntoResponse, Redirect, Response};
use axum::routing::{get, post};
use axum::{Form, Json, Router};
use base64::Engine;
use rand::RngCore;
use serde::Deserialize;
use serde_json::{json, Value};
use sha2::{Digest, Sha256};
use std::collections::HashMap;
use std::sync::Mutex;

/// Mount the discovery + OAuth routes. `server::auth_mw` exempts `/oauth/*` and `/.well-known/*`
/// from the bearer (Origin/Host guard still applies).
pub fn router() -> Router<AppState> {
    Router::new()
        .route("/.well-known/oauth-protected-resource", get(protected_resource))
        .route("/.well-known/oauth-protected-resource/mcp", get(protected_resource))
        .route("/.well-known/oauth-authorization-server", get(as_metadata))
        .route("/.well-known/oauth-authorization-server/mcp", get(as_metadata))
        .route("/oauth/register", post(register))
        .route("/oauth/authorize", get(authorize))
        .route("/oauth/consent", post(consent))
        .route("/oauth/token", post(token))
}

/// Access-token lifetime (7 days) and refresh lifetime (90 days, rotated on every refresh).
const ACCESS_TTL_SECS: i64 = 7 * 86_400;
const REFRESH_TTL_SECS: i64 = 90 * 86_400;
/// Authorization codes are single-use and short-lived.
const CODE_TTL_SECS: i64 = 300;
/// Pending consent transactions expire after 10 minutes.
const TXN_TTL_SECS: i64 = 600;
/// Every OAuth grant carries the execute capability (implies `read` via the scope chain) — the
/// same default a freshly minted `wlk_` key gets.
const GRANTED_SCOPE: &str = "run";

fn now_unix() -> i64 {
    chrono::Utc::now().timestamp()
}

fn sha256_hex(bytes: &[u8]) -> String {
    let mut h = Sha256::new();
    h.update(bytes);
    h.finalize().iter().map(|b| format!("{b:02x}")).collect()
}

/// 32 bytes of OS entropy, base64url — the raw credential material for ids/codes/tokens.
fn random_token(prefix: &str) -> String {
    let mut b = [0u8; 32];
    rand::rngs::OsRng.fill_bytes(&mut b);
    format!("{prefix}{}", base64::engine::general_purpose::URL_SAFE_NO_PAD.encode(b))
}

/// The origin the CLIENT is talking to, reconstructed from the Host header: scheme is `https` iff
/// the host's port is the TLS lane's port (both lanes serve this router). Fallback: plain loopback.
pub fn base_url_for_host(host: Option<&str>, cfg: &LocalConfig) -> String {
    match host {
        Some(h) if !h.trim().is_empty() => {
            let h = h.trim();
            let https = cfg.tls_port != 0 && h.ends_with(&format!(":{}", cfg.tls_port));
            format!("{}://{}", if https { "https" } else { "http" }, h)
        }
        _ => format!("http://127.0.0.1:{}", cfg.port),
    }
}

/// `GET /.well-known/oauth-protected-resource[/mcp]` — RFC 9728. Points the client at OUR OWN
/// authorization server (same origin).
async fn protected_resource(State(st): State<AppState>, Host(host): Host) -> Json<Value> {
    let base = base_url_for_host(Some(&host), &st.config);
    Json(json!({
        "resource": format!("{base}/mcp"),
        "authorization_servers": [base],
        "bearer_methods_supported": ["header"],
        "scopes_supported": [GRANTED_SCOPE],
        "resource_name": "Writ (local)",
    }))
}

/// `GET /.well-known/oauth-authorization-server[/mcp]` — RFC 8414 metadata. Public clients + PKCE
/// S256 only; no client secrets anywhere.
async fn as_metadata(State(st): State<AppState>, Host(host): Host) -> Json<Value> {
    let base = base_url_for_host(Some(&host), &st.config);
    Json(json!({
        "issuer": base,
        "authorization_endpoint": format!("{base}/oauth/authorize"),
        "token_endpoint": format!("{base}/oauth/token"),
        "registration_endpoint": format!("{base}/oauth/register"),
        "response_types_supported": ["code"],
        "grant_types_supported": ["authorization_code", "refresh_token"],
        "code_challenge_methods_supported": ["S256"],
        "token_endpoint_auth_methods_supported": ["none"],
        "scopes_supported": [GRANTED_SCOPE],
    }))
}

// ── Dynamic client registration (RFC 7591) ───────────────────────────────────────────────────────

#[derive(Debug, Deserialize)]
struct RegisterBody {
    redirect_uris: Vec<String>,
    #[serde(default)]
    client_name: Option<String>,
    // Accepted-and-ignored standard fields so strict clients don't fail on extras.
    #[serde(default)]
    #[allow(dead_code)]
    grant_types: Option<Vec<String>>,
    #[serde(default)]
    #[allow(dead_code)]
    response_types: Option<Vec<String>>,
    #[serde(default)]
    #[allow(dead_code)]
    token_endpoint_auth_method: Option<String>,
    #[serde(default)]
    #[allow(dead_code)]
    scope: Option<String>,
}

/// Syntactic gate for a registered redirect URI: absolute (custom app schemes like `claude://…`
/// included — native-app OAuth uses them), no whitespace/fragment, sane length. EXACT string match
/// is enforced at authorize time, so this only needs to reject garbage.
fn redirect_uri_ok(uri: &str) -> bool {
    !uri.is_empty()
        && uri.len() <= 2048
        && uri.contains("://")
        && !uri.contains(char::is_whitespace)
        && !uri.contains('#')
}

/// `POST /oauth/register` — mint a public client id for the presented redirect URIs.
async fn register(State(st): State<AppState>, Json(body): Json<RegisterBody>) -> Response {
    if body.redirect_uris.is_empty()
        || body.redirect_uris.len() > 10
        || !body.redirect_uris.iter().all(|u| redirect_uri_ok(u))
    {
        return (
            StatusCode::BAD_REQUEST,
            Json(json!({"error": "invalid_redirect_uri", "error_description": "1–10 absolute redirect URIs required"})),
        )
            .into_response();
    }
    let client_name = body
        .client_name
        .as_deref()
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .map(|s| s.chars().take(200).collect::<String>());

    let client_id = random_token("wcl_");
    let uris_json = serde_json::to_string(&body.redirect_uris).unwrap_or_else(|_| "[]".into());
    match store::insert_client(&st.db, &client_id, client_name.as_deref(), &uris_json).await {
        Ok(row) => (
            StatusCode::CREATED,
            Json(json!({
                "client_id": row.client_id,
                "client_name": row.client_name,
                "redirect_uris": body.redirect_uris,
                "token_endpoint_auth_method": "none",
                "grant_types": ["authorization_code", "refresh_token"],
                "response_types": ["code"],
            })),
        )
            .into_response(),
        Err(e) => e.into_response(),
    }
}

// ── Authorize + consent ──────────────────────────────────────────────────────────────────────────

/// A consent transaction awaiting the user's click. In-memory on purpose: a daemon restart simply
/// aborts pending flows (the client retries), and nothing secret is at rest.
/// `Debug` is hand-written: `code_challenge` is the PKCE verifier commitment for an in-flight
/// authorization and `state` is client-supplied opaque data. Neither belongs in a log line.
#[derive(Clone)]
struct PendingAuthz {
    client_id: String,
    client_name: String,
    redirect_uri: String,
    code_challenge: String,
    state: Option<String>,
    created_unix: i64,
}

impl std::fmt::Debug for PendingAuthz {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("PendingAuthz")
            .field("client_id", &self.client_id)
            .field("client_name", &self.client_name)
            .field("redirect_uri", &self.redirect_uri)
            .field("created_unix", &self.created_unix)
            .field("code_challenge", &"<redacted>")
            .field("state", &self.state.as_ref().map(|_| "<redacted>"))
            .finish()
    }
}

static PENDING: Mutex<Option<HashMap<String, PendingAuthz>>> = Mutex::new(None);

fn pending_insert(txn: String, p: PendingAuthz) {
    let mut guard = PENDING.lock().unwrap();
    let map = guard.get_or_insert_with(HashMap::new);
    // Opportunistic expiry sweep — the map only ever holds in-flight consents.
    let now = now_unix();
    map.retain(|_, v| now - v.created_unix < TXN_TTL_SECS);
    map.insert(txn, p);
}

fn pending_take(txn: &str) -> Option<PendingAuthz> {
    let mut guard = PENDING.lock().unwrap();
    let map = guard.get_or_insert_with(HashMap::new);
    let p = map.remove(txn)?;
    (now_unix() - p.created_unix < TXN_TTL_SECS).then_some(p)
}

/// `Debug` is hand-written: `code_challenge` binds the eventual token exchange and `state` is
/// client-opaque data that has historically carried session identifiers.
#[derive(Deserialize)]
struct AuthorizeQuery {
    #[serde(default)]
    response_type: Option<String>,
    #[serde(default)]
    client_id: Option<String>,
    #[serde(default)]
    redirect_uri: Option<String>,
    #[serde(default)]
    code_challenge: Option<String>,
    #[serde(default)]
    code_challenge_method: Option<String>,
    #[serde(default)]
    state: Option<String>,
    // Accepted-and-ignored: scope (we always grant `run`), resource (RFC 8707 audience).
    #[serde(default)]
    #[allow(dead_code)]
    scope: Option<String>,
    #[serde(default)]
    #[allow(dead_code)]
    resource: Option<String>,
}

impl std::fmt::Debug for AuthorizeQuery {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("AuthorizeQuery")
            .field("response_type", &self.response_type)
            .field("client_id", &self.client_id)
            .field("redirect_uri", &self.redirect_uri)
            .field("code_challenge_method", &self.code_challenge_method)
            .field("scope", &self.scope)
            .field("resource", &self.resource)
            .field("code_challenge", &self.code_challenge.as_ref().map(|_| "<redacted>"))
            .field("state", &self.state.as_ref().map(|_| "<redacted>"))
            .finish()
    }
}

fn html_escape(s: &str) -> String {
    s.replace('&', "&amp;").replace('<', "&lt;").replace('>', "&gt;").replace('"', "&quot;")
}

/// Anti-framing headers for every HTML page this module serves.
///
/// The consent page is the ONE place in the product where a click grants a client a real local
/// credential, so it must never be renderable inside someone else's document. Loopback pages ARE
/// framable from an HTTPS origin (the DNS-rebind Origin/Host guard in `server::auth_mw` inspects the
/// request's Origin — it does not stop a remote page from putting `http://127.0.0.1:8131/...` in an
/// `<iframe>`), which is the classic setup for clickjacking a hidden Approve button.
///
/// Both headers, on purpose: `frame-ancestors 'none'` is the modern directive, `X-Frame-Options: DENY`
/// covers anything that does not implement it. `default-src 'none'`/`style-src 'unsafe-inline'` also
/// pins the page to its own inline content: it loads no script, no font, no image, and cannot be made
/// to — so an injected reference would fetch nothing. `form-action 'self'` keeps the Approve/Deny POST
/// on this origin.
fn html_page_headers() -> [(header::HeaderName, &'static str); 2] {
    [
        (header::X_FRAME_OPTIONS, "DENY"),
        (
            header::CONTENT_SECURITY_POLICY,
            "default-src 'none'; style-src 'unsafe-inline'; form-action 'self'; \
             frame-ancestors 'none'; base-uri 'none'",
        ),
    ]
}

/// A terminal error PAGE (used when we must NOT redirect: unknown client / unregistered URI).
fn authz_error_page(msg: &str) -> Response {
    (
        StatusCode::BAD_REQUEST,
        html_page_headers(),
        Html(format!(
            "<!doctype html><meta charset=\"utf-8\"><title>Writ — authorization error</title>\
             <body style=\"font-family:system-ui;margin:4rem auto;max-width:28rem\">\
             <h2>Can’t authorize</h2><p>{}</p></body>",
            html_escape(msg)
        )),
    )
        .into_response()
}

/// `GET /oauth/authorize` — validate the request, park it as a pending transaction, and render the
/// consent page. Errors on client identity/redirect are PAGES (never redirect an unvalidated URI);
/// later errors redirect per RFC 6749 §4.1.2.1.
async fn authorize(State(st): State<AppState>, Query(q): Query<AuthorizeQuery>) -> LocalResult<Response> {
    // Client + redirect URI first: these decide whether redirecting is safe at all.
    let client_id = match q.client_id.as_deref().filter(|s| !s.is_empty()) {
        Some(c) => c,
        None => return Ok(authz_error_page("Missing client_id.")),
    };
    let client = match store::get_client(&st.db, client_id).await? {
        Some(c) => c,
        None => return Ok(authz_error_page("Unknown client. Register first (POST /oauth/register).")),
    };
    let registered: Vec<String> = serde_json::from_str(&client.redirect_uris).unwrap_or_default();
    let redirect_uri = match q.redirect_uri.as_deref().filter(|s| !s.is_empty()) {
        Some(r) if registered.iter().any(|u| u == r) => r.to_string(),
        Some(_) => return Ok(authz_error_page("redirect_uri is not registered for this client.")),
        None => return Ok(authz_error_page("Missing redirect_uri.")),
    };

    // From here the redirect URI is trusted — spec errors go BACK to the client via redirect.
    let redirect_err = |code: &str, desc: &str| {
        let sep = if redirect_uri.contains('?') { '&' } else { '?' };
        let state = q
            .state
            .as_deref()
            .map(|s| format!("&state={}", urlencode(s)))
            .unwrap_or_default();
        Redirect::to(&format!(
            "{redirect_uri}{sep}error={code}&error_description={}{state}",
            urlencode(desc)
        ))
        .into_response()
    };

    if q.response_type.as_deref() != Some("code") {
        return Ok(redirect_err("unsupported_response_type", "only response_type=code is supported"));
    }
    // OAuth 2.1: PKCE is mandatory; S256 only (plain is rejected).
    let code_challenge = match q.code_challenge.as_deref().filter(|s| !s.is_empty()) {
        Some(c) if q.code_challenge_method.as_deref() == Some("S256") => c.to_string(),
        _ => return Ok(redirect_err("invalid_request", "PKCE with code_challenge_method=S256 is required")),
    };

    let txn = random_token("txn_");
    let client_name = client.client_name.clone().unwrap_or_else(|| "An MCP client".into());
    pending_insert(
        txn.clone(),
        PendingAuthz {
            client_id: client_id.to_string(),
            client_name: client_name.clone(),
            redirect_uri,
            code_challenge,
            state: q.state.clone(),
            created_unix: now_unix(),
        },
    );

    // The consent page: local, self-contained, one decision. The form posts same-origin, so the
    // DNS-rebind Origin guard covers CSRF; the txn id is single-use and short-lived; and
    // `html_page_headers` makes the page unframable so the Approve button cannot be clickjacked.
    let name = html_escape(&client_name);
    Ok((
        html_page_headers(),
        Html(format!(
        r#"<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Writ — connect {name}</title>
<style>
  :root {{ color-scheme: light dark; }}
  body {{ font-family: system-ui, sans-serif; display:flex; min-height:100vh; margin:0; align-items:center; justify-content:center; background:Canvas; color:CanvasText; }}
  .card {{ max-width: 26rem; padding: 2rem 2.25rem; border: 1px solid color-mix(in srgb, CanvasText 15%, transparent); border-radius: 12px; }}
  h1 {{ font-size: 1.15rem; margin: 0 0 .75rem; }}
  p {{ margin: .5rem 0; line-height: 1.45; }}
  .scope {{ font-size:.9rem; padding:.5rem .75rem; border-radius:8px; background: color-mix(in srgb, CanvasText 7%, transparent); }}
  form {{ display:inline; }}
  .row {{ display:flex; gap:.75rem; margin-top:1.5rem; }}
  button {{ flex:1; padding:.6rem 1rem; border-radius:8px; border:1px solid color-mix(in srgb, CanvasText 25%, transparent); background:transparent; color:inherit; font-size:.95rem; cursor:pointer; }}
  button.approve {{ background: CanvasText; color: Canvas; border-color: CanvasText; }}
  small {{ opacity:.65; display:block; margin-top:1.25rem; }}
</style></head><body>
<div class="card">
  <h1>Connect “{name}” to Writ?</h1>
  <p>This app is asking to use your local Writ agent.</p>
  <div class="scope">It will be able to <b>run your workflows and tools</b> and read their results (scope: <code>run</code>). It cannot manage keys, secrets, or device settings.</div>
  <div class="row">
    <form method="post" action="/oauth/consent"><input type="hidden" name="txn" value="{txn}"><input type="hidden" name="action" value="deny"><button type="submit">Deny</button></form>
    <form method="post" action="/oauth/consent"><input type="hidden" name="txn" value="{txn}"><input type="hidden" name="action" value="approve"><button type="submit" class="approve">Approve</button></form>
  </div>
  <small>Writ local agent — this authorization never leaves your machine.</small>
</div></body></html>"#
        )),
    )
        .into_response())
}

/// Percent-encode the small set of characters that matter in a query value. Deliberately minimal
/// (no new dependency): everything unreserved passes through.
fn urlencode(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'.' | b'_' | b'~' => out.push(b as char),
            _ => out.push_str(&format!("%{b:02X}")),
        }
    }
    out
}

/// `Debug` is hand-written: `txn` addresses a pending consent — presenting it is what approves the
/// authorization, so it is a single-use credential, not an identifier.
#[derive(Deserialize)]
struct ConsentForm {
    txn: String,
    action: String,
}

impl std::fmt::Debug for ConsentForm {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("ConsentForm")
            .field("txn", &"<redacted>")
            .field("action", &self.action)
            .finish()
    }
}

/// `POST /oauth/consent` — the user's click. Approve mints a single-use code bound to the PKCE
/// challenge; both outcomes 302 back to the client.
async fn consent(State(st): State<AppState>, Form(f): Form<ConsentForm>) -> LocalResult<Response> {
    let Some(p) = pending_take(&f.txn) else {
        return Ok(authz_error_page("This authorization request expired — retry from the app."));
    };
    let sep = if p.redirect_uri.contains('?') { '&' } else { '?' };
    let state = p.state.as_deref().map(|s| format!("&state={}", urlencode(s))).unwrap_or_default();

    if f.action != "approve" {
        return Ok(Redirect::to(&format!("{}{}error=access_denied{state}", p.redirect_uri, sep)).into_response());
    }

    let code = random_token("wac_");
    store::insert_code(
        &st.db,
        &sha256_hex(code.as_bytes()),
        &p.client_id,
        &p.redirect_uri,
        &p.code_challenge,
        GRANTED_SCOPE,
        now_unix() + CODE_TTL_SECS,
    )
    .await?;
    tracing::info!(client = %p.client_name, "oauth consent approved (code minted)");
    Ok(Redirect::to(&format!("{}{}code={}{state}", p.redirect_uri, sep, urlencode(&code))).into_response())
}

// ── Token endpoint ───────────────────────────────────────────────────────────────────────────────

/// `Debug` is hand-written. Every credential the token endpoint accepts lands in this struct: the
/// authorization `code`, the PKCE `code_verifier`, and the `refresh_token`. A derived `Debug` printed
/// all three verbatim — and this is the one handler where a `tracing` line or an axum rejection message
/// is most likely to format the extracted body.
#[derive(Deserialize)]
struct TokenForm {
    grant_type: String,
    #[serde(default)]
    code: Option<String>,
    #[serde(default)]
    redirect_uri: Option<String>,
    #[serde(default)]
    client_id: Option<String>,
    #[serde(default)]
    code_verifier: Option<String>,
    #[serde(default)]
    refresh_token: Option<String>,
    // Accepted-and-ignored (RFC 8707 audience binding — single-resource server).
    #[serde(default)]
    #[allow(dead_code)]
    resource: Option<String>,
}

impl std::fmt::Debug for TokenForm {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("TokenForm")
            .field("grant_type", &self.grant_type)
            .field("client_id", &self.client_id)
            .field("redirect_uri", &self.redirect_uri)
            .field("resource", &self.resource)
            // Presence matters for diagnosing a malformed grant; the values never do.
            .field("code", &self.code.as_ref().map(|_| "<redacted>"))
            .field("code_verifier", &self.code_verifier.as_ref().map(|_| "<redacted>"))
            .field("refresh_token", &self.refresh_token.as_ref().map(|_| "<redacted>"))
            .finish()
    }
}

/// RFC 6749 §5.2-shaped error.
fn token_err(status: StatusCode, code: &str, desc: &str) -> Response {
    (status, Json(json!({ "error": code, "error_description": desc }))).into_response()
}

/// Mint + persist an access/refresh pair **inside the caller's transaction**, returning the
/// RFC 6749 §5.1 success body.
///
/// Takes the transaction rather than the pool because the grant that authorizes this mint has already
/// CONSUMED a single-use credential (an authorization code, or the previous refresh token). Consuming
/// and minting must commit together: as separate autocommit statements, a failure in between revoked
/// the client's only refresh token without issuing a replacement, permanently locking it out of the
/// local API until the user re-ran the whole authorization flow.
async fn mint_pair(
    tx: &mut sqlx::Transaction<'_, sqlx::Sqlite>,
    client_id: &str,
    scope: &str,
) -> LocalResult<Response> {
    let access = random_token("wlo_");
    let refresh = random_token("wrt_");
    let now = now_unix();
    store::insert_token_with(
        &mut **tx,
        &sha256_hex(access.as_bytes()),
        Some(&sha256_hex(refresh.as_bytes())),
        client_id,
        scope,
        now + ACCESS_TTL_SECS,
        Some(now + REFRESH_TTL_SECS),
    )
    .await?;
    Ok((
        StatusCode::OK,
        [(header::CACHE_CONTROL, "no-store")],
        Json(json!({
            "access_token": access,
            "token_type": "Bearer",
            "expires_in": ACCESS_TTL_SECS,
            "refresh_token": refresh,
            "scope": scope,
        })),
    )
        .into_response())
}

/// `POST /oauth/token` — authorization_code (with PKCE proof) and refresh_token (rotating) grants.
///
/// Both grants consume a single-use credential and immediately mint its replacement. That pair runs in
/// ONE transaction so the two can never diverge.
///
/// Note the deliberate `tx.commit()` on the bind-check failure paths: burning the credential when the
/// presented `client_id`/`redirect_uri` does not match what it was issued for is the pre-existing
/// (and correct, fail-closed) behaviour — rolling back there would hand a mismatching caller unlimited
/// retries against a still-live code or refresh token.
async fn token(State(st): State<AppState>, Form(f): Form<TokenForm>) -> LocalResult<Response> {
    let now = now_unix();
    let out = match f.grant_type.as_str() {
        "authorization_code" => {
            let (Some(code), Some(verifier)) = (f.code.as_deref(), f.code_verifier.as_deref()) else {
                return Ok(token_err(StatusCode::BAD_REQUEST, "invalid_request", "code and code_verifier are required"));
            };
            let mut tx = st.db.begin().await?;
            // Single-use claim (replay finds used=1 → invalid_grant).
            let Some(row) = store::take_code_with(&mut *tx, &sha256_hex(code.as_bytes()), now).await? else {
                return Ok(token_err(StatusCode::BAD_REQUEST, "invalid_grant", "code is invalid, expired, or already used"));
            };
            // Bind checks: client + redirect_uri must match what the code was minted for.
            if f.client_id.as_deref() != Some(row.client_id.as_str()) {
                tx.commit().await?; // keep the code burned — see the fn doc
                return Ok(token_err(StatusCode::BAD_REQUEST, "invalid_grant", "client_id mismatch"));
            }
            if let Some(r) = f.redirect_uri.as_deref() {
                if r != row.redirect_uri {
                    tx.commit().await?;
                    return Ok(token_err(StatusCode::BAD_REQUEST, "invalid_grant", "redirect_uri mismatch"));
                }
            }
            // PKCE S256 proof (constant-time compare via the bearer helper).
            let computed = base64::engine::general_purpose::URL_SAFE_NO_PAD.encode(Sha256::digest(verifier.as_bytes()));
            if !auth::verify_local_bearer(&computed, &row.code_challenge) {
                tx.commit().await?;
                return Ok(token_err(StatusCode::BAD_REQUEST, "invalid_grant", "PKCE verification failed"));
            }
            let resp = mint_pair(&mut tx, &row.client_id, &row.scope).await?;
            tx.commit().await?;
            resp
        }
        "refresh_token" => {
            let Some(refresh) = f.refresh_token.as_deref() else {
                return Ok(token_err(StatusCode::BAD_REQUEST, "invalid_request", "refresh_token is required"));
            };
            let mut tx = st.db.begin().await?;
            // Rotation: claiming revokes the old pair; the replacement is minted in the SAME
            // transaction, so a client can never end up with neither.
            let Some(row) = store::take_refresh_with(&mut *tx, &sha256_hex(refresh.as_bytes()), now).await? else {
                return Ok(token_err(StatusCode::BAD_REQUEST, "invalid_grant", "refresh token is invalid, expired, or rotated"));
            };
            if let Some(cid) = f.client_id.as_deref() {
                if cid != row.client_id {
                    tx.commit().await?; // keep the old pair revoked — see the fn doc
                    return Ok(token_err(StatusCode::BAD_REQUEST, "invalid_grant", "client_id mismatch"));
                }
            }
            let resp = mint_pair(&mut tx, &row.client_id, &row.scope).await?;
            tx.commit().await?;
            resp
        }
        other => {
            return Ok(token_err(
                StatusCode::BAD_REQUEST,
                "unsupported_grant_type",
                &format!("unsupported grant_type '{other}'"),
            ))
        }
    };
    // Housekeeping only — outside the grant transaction so a purge hiccup can never fail a mint.
    let _ = store::purge_expired(&st.db, now).await;
    Ok(out)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::local::config::{LocalConfig, Paths};
    use crate::local::server::build_router;
    use crate::local::{db, engine, vault};
    use axum::body::{to_bytes, Body};
    use axum::http::Request;
    use std::sync::Arc;
    use tower::ServiceExt;

    const TOKEN: &str = "wlt_oauth_secret";

    async fn test_state() -> (tempfile::TempDir, AppState) {
        let dir = tempfile::tempdir().unwrap();
        std::env::set_var("WRIT_HOME", dir.path().join(".writ"));
        let paths = Paths::resolve().unwrap();
        paths.ensure_dirs().unwrap();
        let v = vault::Vault::load_or_create(&paths.root, false).unwrap();
        let pool = db::open(&paths.db(), &v.db_key_hex()).await.unwrap();
        let st = AppState {
            db: pool,
            vault: Arc::new(v),
            engine: Arc::new(engine::StubEngine),
            config: LocalConfig::default(),
            token: Arc::new(TOKEN.to_string()),
            health: crate::local::app::health::DaemonHealth::shared(),
            recorder: None,
        };
        (dir, st)
    }

    async fn send(st: &AppState, req: Request<Body>) -> (u16, Vec<u8>, axum::http::HeaderMap) {
        let resp = build_router(st.clone()).oneshot(req).await.unwrap();
        let status = resp.status().as_u16();
        let headers = resp.headers().clone();
        let bytes = to_bytes(resp.into_body(), 1 << 20).await.unwrap().to_vec();
        (status, bytes, headers)
    }

    fn jget(bytes: &[u8]) -> Value {
        serde_json::from_slice(bytes).unwrap()
    }

    /// Extract `name="txn" value="..."` from the consent HTML.
    fn txn_from_html(html: &str) -> String {
        let marker = "name=\"txn\" value=\"";
        let start = html.find(marker).expect("txn field in consent page") + marker.len();
        html[start..].split('"').next().unwrap().to_string()
    }

    fn query_param(url: &str, key: &str) -> Option<String> {
        let qs = url.split_once('?')?.1;
        qs.split('&').find_map(|kv| {
            let (k, v) = kv.split_once('=')?;
            (k == key).then(|| v.to_string())
        })
    }

    /// The full spec dance a real MCP host runs: discovery → DCR → authorize → consent → token →
    /// authenticated API call with the minted wlo_ bearer → refresh rotation → replay rejection.
    #[tokio::test]
    async fn full_oauth_flow_end_to_end() {
        let _g = crate::local::config::test_env_guard();
        let (_dir, st) = test_state().await;

        // Discovery is bearer-exempt.
        let (code, body, _) = send(
            &st,
            Request::builder()
                .uri("/.well-known/oauth-authorization-server")
                .header("host", "127.0.0.1:8131")
                .body(Body::empty())
                .unwrap(),
        )
        .await;
        assert_eq!(code, 200, "AS metadata must not require a bearer");
        let meta = jget(&body);
        assert_eq!(meta["issuer"], json!("http://127.0.0.1:8131"));
        assert_eq!(meta["code_challenge_methods_supported"], json!(["S256"]));

        let (code, body, _) = send(
            &st,
            Request::builder()
                .uri("/.well-known/oauth-protected-resource/mcp")
                .header("host", "127.0.0.1:8131")
                .body(Body::empty())
                .unwrap(),
        )
        .await;
        assert_eq!(code, 200);
        assert_eq!(jget(&body)["resource"], json!("http://127.0.0.1:8131/mcp"));

        // Dynamic client registration.
        let (code, body, _) = send(
            &st,
            Request::builder()
                .method("POST")
                .uri("/oauth/register")
                .header("content-type", "application/json")
                .body(Body::from(
                    r#"{"redirect_uris":["http://127.0.0.1:33418/callback"],"client_name":"Test MCP Host"}"#,
                ))
                .unwrap(),
        )
        .await;
        assert_eq!(code, 201, "{}", String::from_utf8_lossy(&body));
        let client_id = jget(&body)["client_id"].as_str().unwrap().to_string();
        assert!(client_id.starts_with("wcl_"));

        // Authorize with PKCE (S256).
        let verifier = "test-verifier-string-that-is-long-enough-123456";
        let challenge = base64::engine::general_purpose::URL_SAFE_NO_PAD
            .encode(Sha256::digest(verifier.as_bytes()));
        let (code_http, body, _) = send(
            &st,
            Request::builder()
                .uri(format!(
                    "/oauth/authorize?response_type=code&client_id={client_id}&redirect_uri=http%3A%2F%2F127.0.0.1%3A33418%2Fcallback&code_challenge={challenge}&code_challenge_method=S256&state=xyz123"
                ))
                .header("host", "127.0.0.1:8131")
                .body(Body::empty())
                .unwrap(),
        )
        .await;
        assert_eq!(code_http, 200);
        let html = String::from_utf8_lossy(&body).to_string();
        assert!(html.contains("Test MCP Host"), "consent names the client");
        let txn = txn_from_html(&html);

        // Approve → 302 with code + state.
        let (code_http, _, headers) = send(
            &st,
            Request::builder()
                .method("POST")
                .uri("/oauth/consent")
                .header("content-type", "application/x-www-form-urlencoded")
                .body(Body::from(format!("txn={txn}&action=approve")))
                .unwrap(),
        )
        .await;
        assert_eq!(code_http, 303, "axum Redirect::to uses 303 See Other");
        let loc = headers.get("location").unwrap().to_str().unwrap().to_string();
        assert!(loc.starts_with("http://127.0.0.1:33418/callback?"), "loc={loc}");
        assert_eq!(query_param(&loc, "state").as_deref(), Some("xyz123"));
        let auth_code = query_param(&loc, "code").unwrap();

        // Token exchange (correct PKCE).
        let (code_http, body, _) = send(
            &st,
            Request::builder()
                .method("POST")
                .uri("/oauth/token")
                .header("content-type", "application/x-www-form-urlencoded")
                .body(Body::from(format!(
                    "grant_type=authorization_code&code={auth_code}&client_id={client_id}&redirect_uri=http%3A%2F%2F127.0.0.1%3A33418%2Fcallback&code_verifier={verifier}"
                )))
                .unwrap(),
        )
        .await;
        assert_eq!(code_http, 200, "{}", String::from_utf8_lossy(&body));
        let tok = jget(&body);
        let access = tok["access_token"].as_str().unwrap().to_string();
        let refresh = tok["refresh_token"].as_str().unwrap().to_string();
        assert!(access.starts_with("wlo_"));
        assert_eq!(tok["token_type"], json!("Bearer"));

        // The minted bearer authenticates a real API call (read via the run-scope chain).
        let (code_http, body, _) = send(
            &st,
            Request::builder()
                .uri("/v1/agent")
                .header("authorization", format!("Bearer {access}"))
                .body(Body::empty())
                .unwrap(),
        )
        .await;
        assert_eq!(code_http, 200, "wlo_ bearer works: {}", String::from_utf8_lossy(&body));

        // …and the MCP surface itself.
        let (code_http, body, _) = send(
            &st,
            Request::builder()
                .method("POST")
                .uri("/mcp")
                .header("authorization", format!("Bearer {access}"))
                .header("content-type", "application/json")
                .body(Body::from(r#"{"jsonrpc":"2.0","id":1,"method":"initialize"}"#))
                .unwrap(),
        )
        .await;
        assert_eq!(code_http, 200, "wlo_ bearer opens /mcp: {}", String::from_utf8_lossy(&body));

        // Code replay is rejected (single-use).
        let (code_http, body, _) = send(
            &st,
            Request::builder()
                .method("POST")
                .uri("/oauth/token")
                .header("content-type", "application/x-www-form-urlencoded")
                .body(Body::from(format!(
                    "grant_type=authorization_code&code={auth_code}&client_id={client_id}&code_verifier={verifier}"
                )))
                .unwrap(),
        )
        .await;
        assert_eq!(code_http, 400);
        assert_eq!(jget(&body)["error"], json!("invalid_grant"));

        // Refresh rotation: new pair, old refresh dead, old access revoked.
        let (code_http, body, _) = send(
            &st,
            Request::builder()
                .method("POST")
                .uri("/oauth/token")
                .header("content-type", "application/x-www-form-urlencoded")
                .body(Body::from(format!("grant_type=refresh_token&refresh_token={refresh}&client_id={client_id}")))
                .unwrap(),
        )
        .await;
        assert_eq!(code_http, 200, "{}", String::from_utf8_lossy(&body));
        let access2 = jget(&body)["access_token"].as_str().unwrap().to_string();
        assert_ne!(access, access2);

        let (replay, _, _) = send(
            &st,
            Request::builder()
                .method("POST")
                .uri("/oauth/token")
                .header("content-type", "application/x-www-form-urlencoded")
                .body(Body::from(format!("grant_type=refresh_token&refresh_token={refresh}&client_id={client_id}")))
                .unwrap(),
        )
        .await;
        assert_eq!(replay, 400, "rotated refresh token must be dead");

        let (old_access, _, _) = send(
            &st,
            Request::builder()
                .uri("/v1/agent")
                .header("authorization", format!("Bearer {access}"))
                .body(Body::empty())
                .unwrap(),
        )
        .await;
        assert_eq!(old_access, 401, "rotation revokes the old access token");

        std::env::remove_var("WRIT_HOME");
    }

    #[tokio::test]
    async fn pkce_mismatch_and_scope_ceiling() {
        let _g = crate::local::config::test_env_guard();
        let (_dir, st) = test_state().await;

        // Register + authorize + approve with challenge for verifier A…
        let (_, body, _) = send(
            &st,
            Request::builder()
                .method("POST")
                .uri("/oauth/register")
                .header("content-type", "application/json")
                .body(Body::from(r#"{"redirect_uris":["myapp://cb"]}"#))
                .unwrap(),
        )
        .await;
        let client_id = jget(&body)["client_id"].as_str().unwrap().to_string();
        let challenge =
            base64::engine::general_purpose::URL_SAFE_NO_PAD.encode(Sha256::digest(b"verifier-A"));
        let (_, body, _) = send(
            &st,
            Request::builder()
                .uri(format!(
                    "/oauth/authorize?response_type=code&client_id={client_id}&redirect_uri=myapp%3A%2F%2Fcb&code_challenge={challenge}&code_challenge_method=S256"
                ))
                .header("host", "127.0.0.1:8131")
                .body(Body::empty())
                .unwrap(),
        )
        .await;
        let txn = txn_from_html(&String::from_utf8_lossy(&body));
        let (_, _, headers) = send(
            &st,
            Request::builder()
                .method("POST")
                .uri("/oauth/consent")
                .header("content-type", "application/x-www-form-urlencoded")
                .body(Body::from(format!("txn={txn}&action=approve")))
                .unwrap(),
        )
        .await;
        let loc = headers.get("location").unwrap().to_str().unwrap().to_string();
        let auth_code = query_param(&loc, "code").unwrap();

        // …then present verifier B → invalid_grant, and the code is consumed (no second chance).
        let (code_http, body, _) = send(
            &st,
            Request::builder()
                .method("POST")
                .uri("/oauth/token")
                .header("content-type", "application/x-www-form-urlencoded")
                .body(Body::from(format!(
                    "grant_type=authorization_code&code={auth_code}&client_id={client_id}&code_verifier=verifier-B"
                )))
                .unwrap(),
        )
        .await;
        assert_eq!(code_http, 400);
        assert_eq!(jget(&body)["error"], json!("invalid_grant"));

        // Scope ceiling: a wlo_ token holds `run` — device-management (Manage) must 401/403.
        // (Mint a pair directly through the store to skip a second consent dance.)
        let now = chrono::Utc::now().timestamp();
        crate::local::store::oauth::insert_token(
            &st.db,
            &sha256_hex(b"wlo_direct-access"),
            None,
            &client_id,
            "run",
            now + 3600,
            None,
        )
        .await
        .unwrap();
        // sha256_hex of the RAW bearer is looked up, so present the raw value we hashed.
        let (code_http, _, _) = send(
            &st,
            Request::builder()
                .method("POST")
                .uri("/v1/keys")
                .header("authorization", "Bearer wlo_direct-access")
                .header("content-type", "application/json")
                .body(Body::from(r#"{"name":"escalation"}"#))
                .unwrap(),
        )
        .await;
        assert_eq!(code_http, 403, "run-scoped wlo_ token must not reach device management");

        std::env::remove_var("WRIT_HOME");
    }

    /// The consent page must not be framable: it is the only click in the product that hands out a
    /// local credential, and loopback pages ARE reachable from a remote HTTPS document's `<iframe>`.
    #[tokio::test]
    async fn consent_page_is_not_framable() {
        let _g = crate::local::config::test_env_guard();
        let (_dir, st) = test_state().await;

        let (_, body, _) = send(
            &st,
            Request::builder()
                .method("POST")
                .uri("/oauth/register")
                .header("content-type", "application/json")
                .body(Body::from(r#"{"redirect_uris":["myapp://cb"],"client_name":"Framed"}"#))
                .unwrap(),
        )
        .await;
        let client_id = jget(&body)["client_id"].as_str().unwrap().to_string();
        let challenge =
            base64::engine::general_purpose::URL_SAFE_NO_PAD.encode(Sha256::digest(b"verifier"));
        let (code, _body, headers) = send(
            &st,
            Request::builder()
                .uri(format!(
                    "/oauth/authorize?response_type=code&client_id={client_id}&redirect_uri=myapp%3A%2F%2Fcb&code_challenge={challenge}&code_challenge_method=S256"
                ))
                .header("host", "127.0.0.1:8131")
                .body(Body::empty())
                .unwrap(),
        )
        .await;
        assert_eq!(code, 200);
        assert_eq!(headers.get("x-frame-options").unwrap(), "DENY");
        let csp = headers.get("content-security-policy").unwrap().to_str().unwrap();
        assert!(csp.contains("frame-ancestors 'none'"), "csp={csp}");
        assert!(csp.contains("form-action 'self'"), "csp={csp}");

        // The terminal error page carries them too (it is served on the same origin).
        let (code, _b, headers) = send(
            &st,
            Request::builder()
                .uri("/oauth/authorize?response_type=code&client_id=wcl_nope&redirect_uri=myapp%3A%2F%2Fcb&code_challenge=x&code_challenge_method=S256")
                .header("host", "127.0.0.1:8131")
                .body(Body::empty())
                .unwrap(),
        )
        .await;
        assert_eq!(code, 400);
        assert_eq!(headers.get("x-frame-options").unwrap(), "DENY");

        std::env::remove_var("WRIT_HOME");
    }

    #[tokio::test]
    async fn deny_and_error_paths() {
        let _g = crate::local::config::test_env_guard();
        let (_dir, st) = test_state().await;

        // Unknown client → error PAGE (no redirect).
        let (code, body, _) = send(
            &st,
            Request::builder()
                .uri("/oauth/authorize?response_type=code&client_id=wcl_nope&redirect_uri=myapp%3A%2F%2Fcb&code_challenge=x&code_challenge_method=S256")
                .header("host", "127.0.0.1:8131")
                .body(Body::empty())
                .unwrap(),
        )
        .await;
        assert_eq!(code, 400);
        assert!(String::from_utf8_lossy(&body).contains("Unknown client"));

        // Registered client, DENY → error=access_denied redirect.
        let (_, body, _) = send(
            &st,
            Request::builder()
                .method("POST")
                .uri("/oauth/register")
                .header("content-type", "application/json")
                .body(Body::from(r#"{"redirect_uris":["myapp://cb"],"client_name":"D"}"#))
                .unwrap(),
        )
        .await;
        let client_id = jget(&body)["client_id"].as_str().unwrap().to_string();
        let (_, body, _) = send(
            &st,
            Request::builder()
                .uri(format!(
                    "/oauth/authorize?response_type=code&client_id={client_id}&redirect_uri=myapp%3A%2F%2Fcb&code_challenge=abc&code_challenge_method=S256"
                ))
                .header("host", "127.0.0.1:8131")
                .body(Body::empty())
                .unwrap(),
        )
        .await;
        let txn = txn_from_html(&String::from_utf8_lossy(&body));
        let (code, _, headers) = send(
            &st,
            Request::builder()
                .method("POST")
                .uri("/oauth/consent")
                .header("content-type", "application/x-www-form-urlencoded")
                .body(Body::from(format!("txn={txn}&action=deny")))
                .unwrap(),
        )
        .await;
        assert_eq!(code, 303);
        let loc = headers.get("location").unwrap().to_str().unwrap();
        assert!(loc.contains("error=access_denied"), "loc={loc}");

        // Missing PKCE → redirected spec error (redirect_uri IS registered).
        let (code, _, headers) = send(
            &st,
            Request::builder()
                .uri(format!(
                    "/oauth/authorize?response_type=code&client_id={client_id}&redirect_uri=myapp%3A%2F%2Fcb"
                ))
                .header("host", "127.0.0.1:8131")
                .body(Body::empty())
                .unwrap(),
        )
        .await;
        assert_eq!(code, 303);
        assert!(headers.get("location").unwrap().to_str().unwrap().contains("error=invalid_request"));

        std::env::remove_var("WRIT_HOME");
    }
}

//! `/v1/secrets` REST handlers — list/create/get/delete over `store::vault_secrets`.
//!
//! Secrets are addressed by their UNIQUE TEXT `key` (not an integer id). The plaintext and the
//! vault key NEVER leave the daemon and are NEVER returned over the API. Callers POST the PLAINTEXT
//! `value`; the HANDLER seals it with the keyring-rooted `Vault` before persisting, so the store
//! only ever holds ciphertext (`value_encrypted`). Every response is shaped through `meta` so the
//! ciphertext column can never leak — these endpoints expose metadata ONLY.
//!
//! The sealing AAD binds the ciphertext to its row (`vault_secrets|value_encrypted|<key>`). Because
//! `key` is UNIQUE, this AAD is a stable per-row identity that cannot be relocated to another
//! secret. `open_secret` reads back with the SAME AAD (for future run-time resolution).
//!
//! House style: thin handlers over the store, `LocalResult<Json<_>>` with `?` propagation, no auth
//! layer here (server.rs applies the loopback bearer + Origin/Host middleware at the router level).

use crate::local::error::{LocalError, LocalResult};
use crate::local::server::AppState;
use crate::local::store::vault_secrets::{self, NewVaultSecret, VaultSecret};
use crate::local::vault::Vault;
use axum::extract::{Path, Query, State};
use axum::routing::get;
use axum::{Json, Router};
use serde::Deserialize;
use serde_json::{json, Value};

/// Build the row-binding AAD for a secret's `value_encrypted` column. `key` is UNIQUE, so this is a
/// stable per-row identity that prevents ciphertext relocation across secrets. `pub(crate)` so the
/// concierge's /respond (which vaults "secret"-kind answers) seals with the SAME AAD scheme.
pub(crate) fn value_aad(key: &str) -> String {
    format!("vault_secrets|value_encrypted|{key}")
}

/// App-lock guard for the secret-touching routes (SECURITY_AND_ENTITLEMENTS_SPEC §1.3). When the
/// vault app-lock is engaged and currently LOCKED this returns `LocalError::Locked` (HTTP 423) so a
/// locked desktop cannot list/read/create/delete secrets until the user unlocks via `/v1/vault/unlock`.
/// When the lock is disabled (the default) it is a no-op. The lock lives in a process-global slot
/// (`vault_lock::global`) installed at `lifecycle::bootstrap`.
fn guard_unlocked() -> LocalResult<()> {
    crate::local::vault_lock::global().guard()
}

/// Decrypt a stored secret row back to its plaintext, using the same row-binding AAD it was sealed
/// with. Intended for future run-time credential resolution (NOT wired into runs here — see notes).
/// NEVER log the returned plaintext.
pub fn open_secret(vault: &Vault, row: &VaultSecret) -> LocalResult<String> {
    let bytes = vault.open_field(&row.value_encrypted, &value_aad(&row.key))?;
    String::from_utf8(bytes).map_err(|_| LocalError::Internal("secret is not valid UTF-8".into()))
}

/// Default page size for the list endpoint when `?limit=` is omitted.
const DEFAULT_LIMIT: i64 = 100;
/// Hard cap so a client cannot ask for an unbounded scan.
const MAX_LIMIT: i64 = 500;

/// Mount the secret routes onto the shared `AppState` router. Auth is applied by `server.rs`.
/// Addressed by `key` (TEXT), so the `:key` path segment is the secret's unique name.
pub fn router() -> Router<AppState> {
    Router::new()
        .route("/v1/secrets", get(list).post(create))
        .route("/v1/secrets/:key", get(get_one).delete(remove))
}

/// The "credentials" category stores an email/username + password pair as a JSON object
/// (`{"username","password"}`) in `value_encrypted`, referenced as `{{vault:name.username}}` /
/// `{{vault:name.password}}`. Every other category stores a single opaque value. Mirrors
/// the cloud backend's `vault` router so the desktop vault behaves identically to Writ Cloud.
const CREDENTIAL_CATEGORY: &str = "credentials";
/// The "card" category stores a payment card as a JSON object (`{name,number,expiry,cvc,zip}`),
/// referenced per field as `{{vault:name.number}}` etc. Only a non-secret last-4 is ever exposed.
const CARD_CATEGORY: &str = "card";
/// The known card fields, in the order the cloud accepts/stores them.
const CARD_FIELDS: [&str; 5] = ["name", "number", "expiry", "cvc", "zip"];

/// A secret `name` (== its unique `key`): starts with a letter or underscore, then letters, digits,
/// `_`, `.`, `-`. Mirrors the cloud `SecretCreate.name` pattern `^[a-zA-Z_][a-zA-Z0-9_.-]*$`.
fn valid_name(n: &str) -> bool {
    let mut chars = n.chars();
    match chars.next() {
        Some(c) if c.is_ascii_alphabetic() || c == '_' => {}
        _ => return false,
    }
    chars.all(|c| c.is_ascii_alphanumeric() || matches!(c, '_' | '.' | '-'))
}

/// Keep only known card fields with non-empty string values; strip spaces from the number. Mirrors
/// the cloud `_clean_card`.
fn clean_card(card: &serde_json::Map<String, Value>) -> serde_json::Map<String, Value> {
    let mut out = serde_json::Map::new();
    for field in CARD_FIELDS {
        let Some(val) = card.get(field).and_then(|v| v.as_str()) else { continue };
        let val = val.trim();
        if val.is_empty() {
            continue;
        }
        let val = if field == "number" { val.replace(' ', "") } else { val.to_string() };
        out.insert(field.to_string(), json!(val));
    }
    out
}

/// Decode the non-secret identifier from a "credentials" secret: `(is_credential, username)`. A true
/// credential is a `{username,password}` JSON pair — a flat value stored under the "credentials"
/// category (e.g. an individual login field the AI concierge sealed) is NOT a pair and resolves to
/// `(false, None)` so it renders as a plain single-value secret, never as a broken username/password
/// pair. The password is never decoded here. Decrypt failures fail safe to `(false, None)`.
fn credential_meta(vault: &Vault, s: &VaultSecret) -> (bool, Option<String>) {
    if s.category.as_deref() != Some(CREDENTIAL_CATEGORY) {
        return (false, None);
    }
    let Ok(plaintext) = open_secret(vault, s) else { return (false, None) };
    let Ok(Value::Object(obj)) = serde_json::from_str::<Value>(&plaintext) else { return (false, None) };
    if !obj.contains_key("username") || !obj.contains_key("password") {
        return (false, None);
    }
    (true, obj.get("username").and_then(|u| u.as_str()).map(str::to_string))
}

/// Decode just the last 4 digits of a "card" secret's number (never the full PAN/CVC). `None` when
/// not a card, on decrypt/parse failure, or when the number has fewer than 4 digits.
fn card_last4(vault: &Vault, s: &VaultSecret) -> Option<String> {
    if s.category.as_deref() != Some(CARD_CATEGORY) {
        return None;
    }
    let plaintext = open_secret(vault, s).ok()?;
    let value: Value = serde_json::from_str(&plaintext).ok()?;
    let number = value.get("number").and_then(|n| n.as_str())?;
    let digits: String = number.chars().filter(char::is_ascii_digit).collect();
    (digits.len() >= 4).then(|| digits[digits.len() - 4..].to_string())
}

#[derive(Debug, Default, Deserialize)]
struct ListQuery {
    limit: Option<i64>,
    /// Case-insensitive substring match on the secret name (parity with the cloud `?search`).
    #[serde(default)]
    search: Option<String>,
    /// Restrict to a single category (parity with the cloud `?category`, used e.g. by the card picker).
    #[serde(default)]
    category: Option<String>,
}

impl ListQuery {
    /// Clamp the requested limit into `1..=MAX_LIMIT`, defaulting when unset.
    fn limit(&self) -> i64 {
        self.limit.unwrap_or(DEFAULT_LIMIT).clamp(1, MAX_LIMIT)
    }
}

/// Body for `POST /v1/secrets`. Mirrors the cloud `SecretCreate`: a single-value secret supplies
/// `value`; a credential secret supplies `username` + `password`; a card secret supplies `card`. The
/// caller supplies PLAINTEXT over loopback; the handler seals it before persisting. `key` is accepted
/// as a legacy alias for `name`. Plaintext is never stored in the clear and never logged.
#[derive(Debug, Deserialize)]
struct CreateBody {
    #[serde(default)]
    name: Option<String>,
    /// Legacy alias for `name` (the daemon's original single-value create shape).
    #[serde(default)]
    key: Option<String>,
    #[serde(default)]
    value: Option<String>,
    #[serde(default)]
    username: Option<String>,
    #[serde(default)]
    password: Option<String>,
    #[serde(default)]
    card: Option<serde_json::Map<String, Value>>,
    #[serde(default)]
    description: Option<String>,
    #[serde(default)]
    category: Option<String>,
}

/// Project a secret row to metadata ONLY — the `value_encrypted` ciphertext is never included. Adds
/// the cloud contract fields (`name` == key, `is_credential`, `is_card`, `username`, `card_last4`) by
/// decrypting the non-secret bits of credential/card secrets. The password / full card are never
/// exposed. Mirrors the cloud backend's `vault` router::_secret_response`.
fn meta(vault: &Vault, s: &VaultSecret) -> Value {
    let (is_credential, username) = credential_meta(vault, s);
    let is_card = s.category.as_deref() == Some(CARD_CATEGORY);
    json!({
        "id": s.id,
        "key": s.key,
        "name": s.key,
        "description": s.description,
        "category": s.category,
        "is_credential": is_credential,
        "is_card": is_card,
        "username": username,
        "card_last4": card_last4(vault, s),
        "created_at": s.created_at,
        "updated_at": s.updated_at,
        "last_used_at": s.last_used_at,
        "use_count": s.use_count,
    })
}

/// `GET /v1/secrets` — newest-first metadata list, optionally filtered by `?category`/`?search` and
/// capped by `?limit`. Ciphertext omitted.
async fn list(State(st): State<AppState>, Query(q): Query<ListQuery>) -> LocalResult<Json<Value>> {
    guard_unlocked()?;
    let rows = match q.category.as_deref().filter(|c| !c.is_empty()) {
        Some(cat) => vault_secrets::list_by_category(&st.db, cat).await?,
        None => vault_secrets::list(&st.db, Some(q.limit())).await?,
    };
    let needle = q.search.as_deref().map(str::to_lowercase);
    let items = rows
        .iter()
        .filter(|s| needle.as_ref().is_none_or(|n| s.key.to_lowercase().contains(n)))
        .map(|s| meta(st.vault.as_ref(), s))
        .collect::<Vec<_>>();
    crate::local::vault_lock::global().touch();
    Ok(Json(json!({ "data": items, "count": items.len() })))
}

/// `POST /v1/secrets` — create a single-value, credential (username+password), or card secret. Seals
/// the plaintext handler-side and stores ciphertext only. Returns metadata only. 400 on a duplicate
/// name or invalid input. The plaintext is never logged.
async fn create(State(st): State<AppState>, Json(body): Json<CreateBody>) -> LocalResult<Json<Value>> {
    guard_unlocked()?;
    let name = body.name.clone().or_else(|| body.key.clone()).unwrap_or_default();
    let name = name.trim();
    if name.is_empty() {
        return Err(LocalError::BadRequest("name is required".into()));
    }
    if name.len() > 255 || !valid_name(name) {
        return Err(LocalError::BadRequest(
            "name must start with a letter or underscore and contain only letters, numbers, '_', '.', '-'".into(),
        ));
    }
    // Duplicate names map to a conflict — the daemon has no dedicated 409 variant, so surface a clear
    // 400 (parity with the cloud's 409 message).
    if vault_secrets::get_by_key(&st.db, name).await?.is_some() {
        return Err(LocalError::BadRequest(format!("Secret '{name}' already exists")));
    }

    // Card vs credential (email/username + password) vs single value — same precedence as the cloud.
    let is_card = body.category.as_deref() == Some(CARD_CATEGORY) || body.card.is_some();
    let is_credential = !is_card
        && (body.category.as_deref() == Some(CREDENTIAL_CATEGORY)
            || body.username.is_some()
            || body.password.is_some());
    let (stored, category): (String, Option<String>) = if is_card {
        let card = clean_card(body.card.as_ref().unwrap_or(&serde_json::Map::new()));
        if !card.contains_key("number") || !card.contains_key("expiry") {
            return Err(LocalError::BadRequest("A card secret needs at least a number and an expiry".into()));
        }
        (Value::Object(card).to_string(), Some(CARD_CATEGORY.to_string()))
    } else if is_credential {
        let username = body.username.as_deref().unwrap_or_default();
        let password = body.password.as_deref().unwrap_or_default();
        if username.trim().is_empty() || password.trim().is_empty() {
            return Err(LocalError::BadRequest(
                "A credential secret needs both an email/username and a password".into(),
            ));
        }
        (json!({ "username": username, "password": password }).to_string(), Some(CREDENTIAL_CATEGORY.to_string()))
    } else {
        let value = body.value.clone().unwrap_or_default();
        if value.trim().is_empty() {
            return Err(LocalError::BadRequest("A secret value is required".into()));
        }
        (value, body.category.clone())
    };

    // Seal in the daemon. The vault key lives in the OS keyring; the caller (loopback UI/CLI) cannot
    // seal, so the plaintext arrives here and is converted to ciphertext before it ever hits the DB.
    let value_encrypted = st.vault.seal_field(stored.as_bytes(), &value_aad(name))?;
    let new = NewVaultSecret {
        key: name.to_string(),
        value_encrypted,
        description: body.description.clone(),
        category,
    };
    let s = vault_secrets::insert(&st.db, &new).await?;
    crate::local::vault_lock::global().touch();
    Ok(Json(meta(st.vault.as_ref(), &s)))
}

/// `GET /v1/secrets/:key` — one secret's metadata (ciphertext omitted) or 404.
async fn get_one(State(st): State<AppState>, Path(key): Path<String>) -> LocalResult<Json<Value>> {
    guard_unlocked()?;
    let s = vault_secrets::get_by_key(&st.db, &key)
        .await?
        .ok_or_else(|| LocalError::NotFound(format!("secret {key}")))?;
    crate::local::vault_lock::global().touch();
    Ok(Json(meta(st.vault.as_ref(), &s)))
}

/// `DELETE /v1/secrets/:key` — hard-delete by key. 404 if absent.
async fn remove(State(st): State<AppState>, Path(key): Path<String>) -> LocalResult<Json<Value>> {
    guard_unlocked()?;
    let removed = vault_secrets::delete_by_key(&st.db, &key).await?;
    if !removed {
        return Err(LocalError::NotFound(format!("secret {key}")));
    }
    Ok(Json(json!({ "key": key, "deleted": true })))
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::local::engine::StubEngine;
    use crate::local::vault::Vault;
    use std::sync::Arc;

    /// A plaintext-in / ciphertext-at-rest fixture: an `AppState` over a fresh SQLCipher DB keyed by
    /// a headless (no-keyring) vault, plus the same `Vault` Arc for direct decrypt assertions.
    async fn fixture() -> (AppState, Arc<Vault>) {
        let dir = Box::leak(Box::new(tempfile::tempdir().unwrap()));
        let vault = Arc::new(Vault::load_or_create(dir.path(), false).unwrap());
        let pool = crate::local::db::open(&dir.path().join("t.db"), &vault.db_key_hex())
            .await
            .unwrap();
        let st = AppState {
            db: pool,
            vault: vault.clone(),
            engine: Arc::new(StubEngine),
            config: crate::local::config::LocalConfig::default(),
            token: Arc::new("wlt_test".to_string()),
            health: crate::local::app::health::DaemonHealth::shared(),
            recorder: None,
        };
        (st, vault)
    }

    /// A single-value secret create body (category `api_keys` — the "credentials" category now means
    /// a username+password pair, so a flat test value uses a plain category).
    fn body(name: &str, value: &str) -> Json<CreateBody> {
        Json(CreateBody {
            name: Some(name.to_string()),
            key: None,
            value: Some(value.to_string()),
            username: None,
            password: None,
            card: None,
            description: Some("a test secret".into()),
            category: Some("api_keys".into()),
        })
    }

    #[tokio::test]
    async fn create_seals_plaintext_and_stores_ciphertext_only() {
        let (st, vault) = fixture().await;
        let plaintext = "hunter2-SUPER-SECRET";

        // POST plaintext → handler seals → metadata response (no secret material).
        let resp = create(State(st.clone()), body("OPENAI_KEY", plaintext)).await.unwrap();
        let v = resp.0;
        assert_eq!(v["key"], "OPENAI_KEY");
        assert!(v.get("value").is_none(), "create response must not echo plaintext");
        assert!(v.get("value_encrypted").is_none(), "create response must not include ciphertext");

        // The stored row holds a WF1: ciphertext blob, and the plaintext appears NOWHERE in it.
        let row = vault_secrets::get_by_key(&st.db, "OPENAI_KEY").await.unwrap().unwrap();
        assert!(row.value_encrypted.starts_with("WF1:"), "value must be sealed at rest");
        assert!(
            !row.value_encrypted.contains(plaintext),
            "plaintext must never appear in the stored row"
        );

        // Serializing the whole row (worst case) still must not leak the plaintext.
        let row_json = serde_json::to_string(&row).unwrap();
        assert!(!row_json.contains(plaintext), "plaintext must not appear anywhere in the row");

        // open_secret round-trips through the same row-binding AAD.
        let recovered = open_secret(&vault, &row).unwrap();
        assert_eq!(recovered, plaintext);

        // The AAD binds the ciphertext to THIS key: a row whose key was swapped cannot be opened
        // (anti-relocation), proving the blob can't be moved onto another secret.
        let mut relocated = row.clone();
        relocated.key = "STRIPE_KEY".to_string();
        assert!(open_secret(&vault, &relocated).is_err(), "ciphertext must be bound to its key");
    }

    #[tokio::test]
    async fn get_and_list_return_metadata_only() {
        let (st, _vault) = fixture().await;
        let plaintext = "p@ss-LEAK-CANARY";
        let _ = create(State(st.clone()), body("DB_PASSWORD", plaintext)).await.unwrap();

        // GET one → metadata only; neither plaintext nor ciphertext is present.
        let one = get_one(State(st.clone()), Path("DB_PASSWORD".to_string())).await.unwrap().0;
        assert_eq!(one["key"], "DB_PASSWORD");
        assert_eq!(one["name"], "DB_PASSWORD", "name is exposed as an alias of key (cloud parity)");
        assert_eq!(one["category"], "api_keys");
        assert_eq!(one["is_credential"], false);
        assert!(one.get("value").is_none());
        assert!(one.get("value_encrypted").is_none());
        assert!(!serde_json::to_string(&one).unwrap().contains(plaintext));

        // LIST → each item is metadata only; ciphertext column never serialized.
        let listed = list(State(st.clone()), Query(ListQuery::default())).await.unwrap().0;
        assert_eq!(listed["count"], 1);
        let dumped = serde_json::to_string(&listed).unwrap();
        assert!(!dumped.contains(plaintext), "list must not leak plaintext");
        assert!(!dumped.contains("value_encrypted"), "list must not leak the ciphertext column");
    }

