    let v: Value = serde_json::from_slice(&bytes).unwrap();
    assert_eq!(v["error"]["code"], json!(-32600), "empty batch → INVALID_REQUEST");
    assert_eq!(v["id"], Value::Null, "no id available for an empty batch");
}

