#[tokio::test]
async fn mcp_requires_bearer() {
    let st = test_state().await;
    // No Authorization header → the server auth layer rejects before `/mcp` runs.
    let resp = build_router(st)
        .oneshot(
            Request::builder()
                .method("POST")
                .uri("/mcp")
                .header("content-type", "application/json")
                .body(Body::from(r#"{"jsonrpc":"2.0","id":1,"method":"initialize"}"#))
                .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(resp.status(), 401, "MCP transport inherits the loopback bearer gate");
}

use std::collections::HashMap;
use std::sync::Arc;

use axum::extract::ws::{Message, WebSocket};
use axum::extract::{Path, Query, State, WebSocketUpgrade};
use axum::http::{HeaderMap, StatusCode};
use axum::response::IntoResponse;
use tokio::sync::broadcast;

use crate::config::constants;
use crate::server::app::AppState;
use crate::server::auth::ws_request_authorized;

/// 1:1 port of Python websocket_spectate (recorder.py line 10585).
///
/// Read-only WebSocket that receives screenshot frames from a running session.
/// Uses the session's screenshot broadcast channel — spectators subscribe to
/// the same stream the primary recording websocket receives.
pub async fn handler(
    ws: WebSocketUpgrade,
    Path(session_id): Path<String>,
    Query(query): Query<HashMap<String, String>>,
    headers: HeaderMap,
    State(state): State<Arc<AppState>>,
) -> impl IntoResponse {
    if !ws_request_authorized(
        &query,
        &headers,
        &state.config.auth_secret,
        state.config.auth_bypass_enabled(),
    ) {
        return (StatusCode::UNAUTHORIZED, "unauthorized").into_response();
    }
    ws.on_upgrade(move |socket| handle_socket(socket, session_id, state))
        .into_response()
}

async fn handle_socket(
    mut socket: WebSocket,
    session_id: String,
    state: Arc<AppState>,
) {
    tracing::info!(session_id = %session_id, "Spectator WebSocket connected");

    // 1. Check session exists (Python line 10599)
    let screenshot_rx = {
        let session_ref = match state.recorder.get_session_mut(&session_id) {
            Some(s) => s,
            None => {
                let _ = socket.send(Message::Text(
                    serde_json::json!({"type": "error", "message": format!("Session {} not found", session_id)}).to_string(),
                )).await;
                let _ = socket.close().await;
                return;
            }
        };

        // 2. Subscribe to screenshot broadcast (Python: session.spectators.append(websocket))
        match &session_ref.screenshot_tx {
            Some(tx) => {
                if tx.receiver_count() >= constants::MAX_SPECTATORS {
                    let _ = socket.send(Message::Text(
                        serde_json::json!({"type": "error", "message": "Max spectators reached"}).to_string(),
                    )).await;
                    let _ = socket.close().await;
                    return;
                }
                tx.subscribe()
            }
            None => {
                let _ = socket.send(Message::Text(
                    serde_json::json!({"type": "error", "message": "Session not streaming"}).to_string(),
                )).await;
                let _ = socket.close().await;
                return;
            }
        }
    };

    // 3. Send initial info (Python line 10627)
    let current_url = state
        .recorder
        .get_session_mut(&session_id)
        .map(|s| s.current_url.clone())
        .unwrap_or_default();

    let _ = socket.send(Message::Text(
        serde_json::json!({
            "type": "spectate_started",
            "session_id": session_id,
            "url": current_url,
        }).to_string(),
    )).await;

    // 4. Forward frames and handle ping/pong until disconnect
    stream_to_spectator(socket, screenshot_rx, &session_id).await;

    tracing::info!(session_id = %session_id, "Spectator WebSocket disconnected");
}

/// Forward screenshot frames from broadcast channel to spectator websocket.
/// Also handles incoming ping/pong from spectator.
async fn stream_to_spectator(
    mut socket: WebSocket,
    mut screenshot_rx: broadcast::Receiver<Vec<u8>>,
    session_id: &str,
) {
    loop {
        tokio::select! {
            // Forward screenshot frames to spectator
            frame = screenshot_rx.recv() => {
                match frame {
                    Ok(data) => {
                        if socket.send(Message::Binary(data)).await.is_err() {
                            break;
                        }
                    }
                    Err(broadcast::error::RecvError::Lagged(n)) => {
                        tracing::debug!(session_id = %session_id, skipped = n, "Spectator lagged, skipping frames");
                    }
                    Err(broadcast::error::RecvError::Closed) => {
                        tracing::info!(session_id = %session_id, "Session ended, closing spectator");
                        break;
                    }
                }
            }
            // Handle incoming messages from spectator (ping/pong only)
            msg = socket.recv() => {
                match msg {
                    Some(Ok(Message::Text(text))) => {
                        if let Ok(parsed) = serde_json::from_str::<serde_json::Value>(&text) {
                            if parsed.get("type").and_then(|v| v.as_str()) == Some("ping") {
                                let _ = socket.send(Message::Text(
                                    serde_json::json!({"type": "pong"}).to_string(),
                                )).await;
                            }
                        }
                    }
                    Some(Ok(Message::Ping(_))) => {
                        let _ = socket.send(Message::Pong(vec![])).await;
                    }
                    Some(Ok(Message::Close(_))) | None | Some(Err(_)) => break,
                    _ => {}
                }
            }
        }
    }
}

//! Data models for the monitoring subsystem.
//!
//! `Target` / `Selector` deserialize from the `assign_targets` frame; `ReportItem`
//! serializes into the `target_check_batch` frame and matches the backend's
//! `SingleReportData` schema (the cloud backend's `batch_reports` router) exactly.

use serde::{Deserialize, Serialize};
use std::collections::HashMap;

fn default_check_type() -> String {
    "content".to_string()
}
fn default_content_type() -> String {
    "text".to_string()
}
fn default_true() -> bool {
    true
}

/// Parse an optional i64 that may arrive as a JSON number OR a string — the
/// backend sends the target id as `str(target.id)` (a string) while selector ids
/// come as numbers, so be lenient. Missing/null/unparseable → None.
fn de_opt_i64_flex<'de, D>(d: D) -> Result<Option<i64>, D::Error>
where
    D: serde::Deserializer<'de>,
{
    let v = Option::<serde_json::Value>::deserialize(d)?;
    Ok(match v {
        Some(serde_json::Value::Number(n)) => n.as_i64(),
        Some(serde_json::Value::String(s)) => s.trim().parse::<i64>().ok(),
        _ => None,
    })
}

/// One monitored selector within a content target.
#[derive(Debug, Clone, Deserialize)]
pub struct Selector {
    #[serde(default)]
    pub id: Option<i64>,
    #[serde(default)]
    pub name: Option<String>,
    pub selector: String,
    #[serde(default = "default_content_type")]
    pub content_type: String, // text | html | visual
    #[serde(default)]
    pub ignore_regex: Option<String>,
    #[serde(default)]
    pub baseline_hash: Option<String>,
    #[serde(default)]
    pub baseline_content: Option<String>,
    /// For content_type == "visual": the screenshot region to clip and pixel-hash —
    /// `{x, y, width, height, scroll_x, scroll_y, viewport}`. Absent for text/html
    /// selectors. Kept as raw JSON because it is stored and forwarded verbatim;
    /// interpret it ONLY through [`super::visual_region`], which owns the meaning of
    /// `viewport` (x/y are viewport-relative and mean nothing without the frame size
    /// they were measured in).
    #[serde(default)]
    pub visual_region: Option<serde_json::Value>,
}

/// A monitoring target as handed down by the coordinator. Mirrors the
/// desktop-agent target dict.
#[derive(Debug, Clone, Deserialize)]
pub struct Target {
    #[serde(default, deserialize_with = "de_opt_i64_flex")]
    pub id: Option<i64>,
    pub url: String,
    #[serde(default = "default_check_type")]
    pub check_type: String, // content | uptime
    #[serde(default)]
    pub check_period_ms: Option<i64>,
    #[serde(default)]
    pub requires_playwright: bool,
    /// Optional auth/login workflow to run (in the browser) before checking.
    #[serde(default)]
    pub pre_check_workflow: Option<serde_json::Value>,
    /// Saved auth session ({cookies,headers,localStorage,sessionStorage,fingerprint}).
    #[serde(default)]
    pub auth_session: Option<serde_json::Value>,
    #[serde(default)]
    pub timeout_ms: Option<i64>,
    #[serde(default)]
    pub expected_status_code: Option<i64>,
    #[serde(default = "default_true")]
    pub check_ssl: bool,
    #[serde(default)]
    pub selectors: Vec<Selector>,
}

impl Target {
    /// Tiered routing: a target goes through the browser when it needs JS
    /// rendering, an auth session, or a pre-check workflow. Otherwise the fast
    /// HTTP path handles it. (Uptime is always HTTP.)
    pub fn needs_browser(&self) -> bool {
        if self.check_type == "uptime" {
            return false;
        }
        self.requires_playwright
            || self.pre_check_workflow.is_some()
            || self.auth_session.is_some()
            // A visual (screenshot-region) selector can ONLY be captured in the
            // browser — the HTTP path has no page to clip. Force the browser path
            // whenever any selector is visual, regardless of requires_playwright.
            || self
                .selectors
                .iter()
                .any(|s| s.content_type == "visual" && s.visual_region.is_some())
    }
}

/// One report item — matches `SingleReportData` in the backend batch endpoint.
/// `None` fields are omitted so the payload stays identical to the Python agent.
#[derive(Debug, Clone, Serialize, Default)]
pub struct ReportItem {
    pub target_url: String,
    pub check_type: String,

    /// Id of the target checked (the coalesced group's representative). Lets the
    /// backend fan an uptime result out to the exact fetch_key group.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub target_id: Option<i64>,

    #[serde(skip_serializing_if = "Option::is_none")]
    pub selector_id: Option<i64>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub selector_name: Option<String>,

    // Content fields
    #[serde(skip_serializing_if = "Option::is_none")]
    pub content_hash: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub diff_snippet: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub content: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub previous_content: Option<String>,
    /// Base64 PNG of a visual zone's region (first run + on change) for the
    /// before/after image diff. Omitted for text/html and steady-state visual.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub screenshot: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub headers: Option<HashMap<String, String>>,

    // Uptime fields
    #[serde(skip_serializing_if = "Option::is_none")]
    pub is_up: Option<bool>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub response_time_ms: Option<i64>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub dns_time_ms: Option<i64>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub connect_time_ms: Option<i64>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub tls_time_ms: Option<i64>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub ssl_cert_valid: Option<bool>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub ssl_cert_expires_at: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub ssl_cert_days_until_expiry: Option<i64>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub ssl_cert_issuer: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub ssl_cert_subject: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub ssl_error: Option<String>,

    // Common
    #[serde(skip_serializing_if = "Option::is_none")]
    pub status_code: Option<i64>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub error_type: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub error_message: Option<String>,
}

/// The result of checking a single target: the report items to batch up, plus an
/// optional refreshed auth session (when a browser/pre-check ran) to persist via
/// `precheck_complete`, and whether any selector changed (for adaptive scheduling).
#[derive(Debug, Clone, Default)]
pub struct CheckOutcome {
    pub reports: Vec<ReportItem>,
    pub auth_session: Option<serde_json::Value>,
    pub changed: bool,
}

//! SQLCipher cipher-gate — the CI proof that the encrypted local DB layer is genuinely linked.
//!
//! This is the integration-test counterpart to `crate::local::db`'s in-file unit tests. It is
//! ADDITIVE (net-new file) and only compiles under the `local` cargo feature, so the default
//! (cloud) `writ-agent` build is byte-unchanged and never sees it.
//!
//! Ground truth (PRODUCTION_READINESS.md + SECURITY_AND_ENTITLEMENTS_SPEC.md §1.5):
//!   The whole DB is SQLCipher-encrypted at rest and `crate::local::db::open` carries a LOAD-BEARING
//!   fail-closed assert: an empty `PRAGMA cipher_version` means sqlx linked PLAIN SQLite and
//!   `PRAGMA key` silently no-op'd, leaving the DB plaintext while appearing encrypted. If the
//!   `libsqlite3-sys` `bundled-sqlcipher-*` feature ever stops unifying onto sqlx's sqlite driver,
//!   the binary would happily write secrets in the clear. This gate FAILS the build before that ships.
//!
//! Two independent assertions, each sufficient on its own to catch a de-linked cipher:
//!   1. cipher_version is non-empty  — `db::assert_cipher_active` returns Err(CipherUnavailable)
//!      when `PRAGMA cipher_version` is empty (plain SQLite linked).
//!   2. wrong key errors             — re-opening an existing encrypted DB with the WRONG key must
//!      fail (the encrypted header won't decrypt). With plain SQLite linked, `PRAGMA key` is a
//!      no-op and the wrong-key open would SUCCEED — so a success here is a cipher regression.
//!   3. (belt) encrypted at rest     — the file must NOT start with the plaintext SQLite magic.
//!
//! Run locally:  cargo test --features local --test cipher_gate
//! Run in CI:    cargo test --features local local::            (the in-file db::tests)
//!               cargo test --features local --test cipher_gate (this file)

#![cfg(feature = "local")]

use writ_agent::local::db;

const GOOD_KEY: &str = "correct-horse-battery-staple-42";
const WRONG_KEY: &str = "this-is-not-the-key-totally-different";

/// (1) cipher_version non-empty AND (3) encrypted-at-rest header check.
#[tokio::test]
async fn cipher_version_is_non_empty_and_file_is_encrypted_at_rest() {
    let dir = tempfile::tempdir().expect("tempdir");
    let path = dir.path().join("cipher_gate.db");

    // `open` internally calls `assert_cipher_active`, so a successful open already proves a
    // non-empty cipher_version. We ALSO assert it explicitly here as the documented gate.
    let pool = db::open(&path, GOOD_KEY)
        .await
        .expect("open encrypted DB with correct key");

    db::assert_cipher_active(&pool)
        .await
        .expect("PRAGMA cipher_version must be non-empty (SQLCipher must be linked)");

    pool.close().await;

    // The on-disk file must be SQLCipher-encrypted: a plaintext SQLite DB begins with the
    // 16-byte magic "SQLite format 3\0". Its presence means the cipher silently no-op'd.
    let bytes = std::fs::read(&path).expect("read db file");
    assert!(
        !bytes.starts_with(b"SQLite format 3\0"),
        "DB MUST be SQLCipher-encrypted at rest — found plaintext SQLite header (cipher de-linked)"
    );
}

/// (2) Opening an existing encrypted DB with the WRONG key must error.
#[tokio::test]
async fn wrong_key_fails_to_open_encrypted_db() {
    let dir = tempfile::tempdir().expect("tempdir");
    let path = dir.path().join("wrong_key.db");

    // Create + key + migrate with the correct key, then close so the file exists encrypted.
    let pool = db::open(&path, GOOD_KEY)
        .await
        .expect("create encrypted DB with correct key");
    pool.close().await;

    // Re-open the SAME file with the WRONG key. SQLCipher cannot decrypt the header, so the
    // first access (cipher assert / integrity check / migrate) fails and `open` returns Err.
    // If plain SQLite were linked, `PRAGMA key` would be a no-op and this would WRONGLY succeed.
    let result = db::open(&path, WRONG_KEY).await;
    assert!(
        result.is_err(),
        "opening an encrypted DB with the WRONG key MUST fail — it succeeded, so SQLCipher is not \
         actually enforcing encryption (cipher de-linked)"
    );
}

//! Hardware-derived capacity. Port of the relevant maths in
//! `desktop-agent/lib/hardware_profiler.py` (HTTP mode). Produces the `capacity`
//! object advertised on connect and consumed by the backend distributor.

use serde::Serialize;
use sysinfo::System;

// Resource cost per HTTP check / safety margins — same constants as Python.
const HTTP_CPU_PERCENT: f64 = 0.5;
const HTTP_RAM_MB: f64 = 10.0;
const CPU_RESERVE_PERCENT: f64 = 20.0;
const RAM_RESERVE_PERCENT: f64 = 25.0;
const THREAD_POOL_STARTUP_MS: f64 = 50.0;
const COORDINATION_OVERHEAD_MS: f64 = 15.0;
const CONSERVATIVE_MARGIN: f64 = 0.65;

// Default latency model when we haven't benchmarked (Python's fallback).
const DEFAULT_AVG_LATENCY_MS: f64 = 200.0;
const DEFAULT_P95_LATENCY_MS: f64 = 350.0;

/// Capacity report — field names match `agent.meta['capacity']` on the backend.
#[derive(Debug, Clone, Serialize)]
pub struct CapacityReport {
    pub cpu_cores: usize,
    pub cpu_threads: usize,
    pub ram_total_gb: f64,
    pub check_mode: String,
    pub parallel_workers: usize,
    pub avg_check_latency_ms: f64,
    pub timeslots_needed: usize,
    pub targets_per_timeslot: usize,
    pub total_capacity: usize,
}

impl CapacityReport {
    /// Profile the host and compute capacity for the given global period.
    pub fn profile(global_period_ms: i64) -> Self {
        let mut sys = System::new();
        sys.refresh_memory();
        // CPU usage is a DELTA between two refreshes: the very first `refresh_cpu_usage()` has no prior
        // sample and reports ~0%, which would over-estimate available CPU (→ inflated worker count).
        // Prime, wait the library's minimum sampling interval, then refresh again for a real reading.
        sys.refresh_cpu_usage();
        std::thread::sleep(sysinfo::MINIMUM_CPU_UPDATE_INTERVAL);
        sys.refresh_cpu_usage();

        let cpu_threads = std::thread::available_parallelism().map(|n| n.get()).unwrap_or(4);
        let cpu_cores = (cpu_threads / 2).max(1);
        let ram_total_gb = sys.total_memory() as f64 / 1_073_741_824.0; // bytes → GiB
        let ram_available_gb = sys.available_memory() as f64 / 1_073_741_824.0;
        let cpu_usage_percent = sys.global_cpu_info().cpu_usage() as f64;

        let parallel_workers =
            Self::parallel_workers(cpu_threads, ram_total_gb, ram_available_gb, cpu_usage_percent);

        let targets_per_timeslot =
            Self::targets_per_timeslot(global_period_ms.max(1) as f64, parallel_workers);

        // One timeslot is enough for a single agent; the backend expands slots
        // across the fleet. We advertise a single slot of our realistic capacity.
        let timeslots_needed = 1;
        let total_capacity = targets_per_timeslot * timeslots_needed;

        Self {
            cpu_cores,
            cpu_threads,
            ram_total_gb,
            check_mode: "http".to_string(),
            parallel_workers,
            avg_check_latency_ms: DEFAULT_AVG_LATENCY_MS,
            timeslots_needed,
            targets_per_timeslot,
            total_capacity,
        }
    }

    fn parallel_workers(
        cpu_threads: usize,
        ram_total_gb: f64,
        ram_available_gb: f64,
        cpu_usage_percent: f64,
    ) -> usize {
        let available_cpu_percent =
            (100.0 - CPU_RESERVE_PERCENT - cpu_usage_percent).clamp(10.0, 80.0);
        let mut available_ram_gb = ram_total_gb * (1.0 - RAM_RESERVE_PERCENT / 100.0);
        available_ram_gb = available_ram_gb.min(ram_available_gb).max(0.0);

        let max_workers_cpu = (available_cpu_percent / HTTP_CPU_PERCENT) as i64;
        let max_workers_ram = ((available_ram_gb * 1024.0) / HTTP_RAM_MB) as i64;
        let mut max_workers = max_workers_cpu.min(max_workers_ram);
        // HTTP is I/O bound — allow more parallelism than threads.
        max_workers = max_workers.min(cpu_threads as i64 * 10);
        max_workers.clamp(1, 200) as usize
    }

    /// Realistic per-timeslot target capacity (Python
    /// `calculate_timeslot_capacity_realistic`, conservative margin).
    fn targets_per_timeslot(timeslot_duration_ms: f64, parallel_workers: usize) -> usize {
        let effective_time = (timeslot_duration_ms - THREAD_POOL_STARTUP_MS).max(0.0);
        let effective_latency_p95 = DEFAULT_P95_LATENCY_MS + COORDINATION_OVERHEAD_MS;
        let batches = if effective_latency_p95 > 0.0 {
            effective_time / effective_latency_p95
        } else {
            0.0
        };
        let realistic = (batches * parallel_workers as f64) as i64;
        ((realistic as f64 * CONSERVATIVE_MARGIN) as i64).max(1) as usize
    }

    pub fn to_json(&self) -> serde_json::Value {
        serde_json::to_value(self).unwrap_or_else(|_| serde_json::json!({}))
    }
}

//! `assign_targets` / `target_sync` / `assign_workflows` — cloud monitoring/workflow assignment frames.
//!
//! A user-hosted DESKTOP is a BYO execution agent for the OWNER's own work — it is NOT a node in the
//! shared monitoring-distribution fleet. The cloud's `assign_targets` distributes monitor TARGETS from
//! the shared fleet (potentially OTHER tenants' targets) across fleet agents; persisting those into the
//! desktop's local `targets` store would (a) surface FOREIGN monitors the user never created and (b)
//! make the local scheduler actually CHECK them on the user's machine. That is wrong on both privacy
//! and correctness grounds.
//!
//! So these frames are ACK-ONLY here: NOTHING is ever written to the local store. The desktop runs ONLY
//! the user's OWN local monitors (created locally, or explicitly synced from the cloud). The agent also
//! no longer advertises the `monitoring` capability in its connect body, so the backend should not send
//! these at all — this handler is the defense-in-depth second line if one still arrives.
//!
//! SECURITY (the never-trust-a-BYO-agent rule): identity/billing stay server-side; a non-panicking ack
//! that persists nothing can leak nothing and can never run a foreign tenant's check on this device.

use serde_json::{json, Value};

/// Handle `assign_targets` / `target_sync`: ACK WITHOUT PERSISTING. The desktop never adopts cloud-
/// pushed monitor targets (see module docs) — it runs only the user's own local monitors. Returns the
/// ack frame for the router to send. Never touches the local store; never panics.
pub fn handle_assign_targets(msg: &Value) -> Value {
    let assignment_id = msg["assignment_id"].as_str().unwrap_or("").to_string();
    let count = msg
        .get("targets")
        .and_then(Value::as_array)
        .map(|a| a.len())
        .unwrap_or(0);
    tracing::info!(
        assignment_id,
        count,
        "assign_targets IGNORED on a user-hosted BYO agent (runs only its own local monitors; nothing persisted)"
    );
    json!({
        "type": "targets_assigned",
        "assignment_id": assignment_id,
        // Honest: the agent does NOT accept shared-fleet monitor assignment.
        "success": false,
        "inserted": 0,
        "updated": 0,
        "skipped": count,
        "error": "monitor assignment is not accepted on a user-hosted agent (it runs only your own local monitors)",
    })
}

/// Handle `assign_workflows`: ACK accepted-but-not-persisted (the workflows still run cloud-side). The
/// desktop has no cloud→local workflow id map and never adopts pushed assignments. Non-panicking.
pub fn handle_assign_workflows(msg: &Value) -> Value {
    let assignment_id = msg["assignment_id"].as_str().unwrap_or("").to_string();
    let count = msg
        .get("workflows")
        .and_then(Value::as_array)
        .map(|a| a.len())
        .unwrap_or(0);
    tracing::info!(
        assignment_id,
        count,
        "assign_workflows acknowledged (not persisted on this agent)"
    );
    json!({
        "type": "workflows_assigned",
        "assignment_id": assignment_id,
        "success": false,
        "accepted": count,
        "persisted": 0,
        "error": "workflow assignment is not persisted on this agent",
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn assign_targets_acks_without_persisting() {
        // Even a well-formed assignment is REFUSED (not persisted) — the desktop never adopts foreign
        // monitor targets. The ack reports the count as skipped and success:false.
        let frame = json!({
            "type": "assign_targets",
            "assignment_id": "asg-1",
            "targets": [
                {"url": "https://a.example.com", "check_type": "content"},
                {"url": "https://b.example.com", "check_type": "uptime"}
            ]
        });
        let ack = handle_assign_targets(&frame);
        assert_eq!(ack["type"], "targets_assigned");
        assert_eq!(ack["assignment_id"], "asg-1");
        assert_eq!(ack["success"], false, "user-hosted agent does not adopt shared-fleet monitors");
        assert_eq!(ack["inserted"], 0);
        assert_eq!(ack["updated"], 0);
        assert_eq!(ack["skipped"], 2);
        assert!(ack["error"].as_str().unwrap().contains("your own local monitors"));
    }

    #[test]
    fn assign_targets_empty_list_is_a_clean_ack() {
        let ack = handle_assign_targets(&json!({"assignment_id": "asg-empty"}));
        assert_eq!(ack["type"], "targets_assigned");
        assert_eq!(ack["skipped"], 0);
        assert_eq!(ack["inserted"], 0);
    }

    #[test]
    fn assign_workflows_acks_not_persisted() {
        let ack = handle_assign_workflows(&json!({
            "assignment_id": "wf-asg",
            "workflows": [{"id": 1}, {"id": 2}]
        }));
        assert_eq!(ack["type"], "workflows_assigned");
        assert_eq!(ack["success"], false, "honestly not persisted on this agent");
        assert_eq!(ack["accepted"], 2);
        assert_eq!(ack["persisted"], 0);
    }
}

//! `/v1/billing/*` REST handlers — READ-ONLY cloud billing reflection for a linked account.
//!
//! The desktop webview's usage surfaces (Account page, sidebar Usage modal, the crawl
//! wizard's quota hint) read `/v1/billing/usage/limits`, `/v1/billing/account-status`,
//! and the unified-credit `/v1/billing/account/usage` from the LOCAL daemon; these thin
//! handlers forward to the cloud via
//! [`crate::local::cloud::billing`] with the keyring-held `wto_` token. Unlinked → clean
//! 401 (the UI gates these reads on `linked`, so that only happens on a stale webview).
//!
//! Mutations (checkout, portal, plan changes) are DELIBERATELY absent: money moves only
//! in the cloud web app via deep-link. House style: thin handlers, `LocalResult<Json<_>>`
//! with `?` propagation, no auth layer here (server.rs applies the loopback bearer).

use crate::local::error::LocalResult;
use crate::local::server::AppState;
use axum::extract::State;
use axum::routing::get;
use axum::{Json, Router};
use serde_json::Value;

/// Routes for this resource, mounted under the shared `/v1` namespace by the parent router.
pub fn router() -> Router<AppState> {
    Router::new()
        .route("/v1/billing/usage/limits", get(usage_limits))
        .route("/v1/billing/account-status", get(account_status))
        .route("/v1/billing/account/usage", get(account_usage))
}

/// `GET /v1/billing/usage/limits` — the linked plan's per-resource usage vs. limits.
async fn usage_limits(State(st): State<AppState>) -> LocalResult<Json<Value>> {
    Ok(Json(crate::local::cloud::billing::usage_limits(&st.db).await?))
}

/// `GET /v1/billing/account-status` — wallet balance, billing-period window, overage flags.
async fn account_status(State(st): State<AppState>) -> LocalResult<Json<Value>> {
    Ok(Json(crate::local::cloud::billing::account_status(&st.db).await?))
}

/// `GET /v1/billing/account/usage` — the canonical unified-credit usage summary the
/// desktop credit surfaces read (three credit pools + residential funding + reset date).
async fn account_usage(State(st): State<AppState>) -> LocalResult<Json<Value>> {
    Ok(Json(crate::local::cloud::billing::account_usage(&st.db).await?))
}

//! Test-only manifest signing — the deterministic Ed25519 test keypair (its public half is pinned in
//! [`super::manifest`] under the same cfg) plus a [`sign_manifest`] helper that reproduces exactly
//! what `scripts/desktop/sign-update-manifest.sh` does: canonicalize `signed` (JCS), Ed25519-sign the
//! canonical bytes, and stamp `kid` + base64url(unpadded) `signature`.
//!
//! This is compiled ONLY under `#[cfg(any(test, feature = "update-test-keys"))]` — it is NEVER in a
//! shipped feature set, so no test key ever reaches production and no signing capability ships.

use super::manifest::{canonicalize_signed, Manifest, Signed};

/// The `kid` stamped by [`sign_manifest`] and pinned (test-only) in `manifest.rs`.
pub const TEST_KID: &str = "wtu-test-2026";

/// Raw 32-byte Ed25519 PRIVATE seed (deterministic: bytes `01..=20`). The matching public key is
/// [`TEST_PUBKEY_HEX`]. Test-only; deliberately fixed so signatures are reproducible.
pub const TEST_SEED: [u8; 32] = [
    0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x0e, 0x0f, 0x10,
    0x11, 0x12, 0x13, 0x14, 0x15, 0x16, 0x17, 0x18, 0x19, 0x1a, 0x1b, 0x1c, 0x1d, 0x1e, 0x1f, 0x20,
];

/// Raw 32-byte Ed25519 PUBLIC key (hex) derived from [`TEST_SEED`] via RFC 8032. Pinned in
/// `manifest.rs`'s test key table so a manifest signed by [`sign_manifest`] verifies.
pub const TEST_PUBKEY_HEX: &str =
    "79b5562e8fe654f94078b112e8a98ba7901f853ae695bed7e0e3910bad049664";

/// A SECOND, UNPINNED Ed25519 seed — used to forge a wrong-key signature (the wrong-key reject test).
pub const WRONG_SEED: [u8; 32] = [
    0xa1, 0xa2, 0xa3, 0xa4, 0xa5, 0xa6, 0xa7, 0xa8, 0xa9, 0xaa, 0xab, 0xac, 0xad, 0xae, 0xaf, 0xb0,
    0xb1, 0xb2, 0xb3, 0xb4, 0xb5, 0xb6, 0xb7, 0xb8, 0xb9, 0xba, 0xbb, 0xbc, 0xbd, 0xbe, 0xbf, 0xc0,
];

/// Sign a `signed` payload with the given raw seed under `kid`, returning the full manifest JSON
/// bytes (schema_version 1 + kid + base64url signature + the pretty-serialized `signed`). Reproduces
/// the signing script: the signature covers the JCS-canonical bytes of `signed`, and the emitted
/// `signed` bytes are the caller's `serde_json` serialization (the verifier re-canonicalizes from the
/// raw wire, so the emitted formatting is irrelevant to verification).
pub fn sign_manifest_with(seed: &[u8; 32], kid: &str, signed: &Signed) -> Vec<u8> {
    use base64::Engine;
    use ed25519_dalek::{Signer, SigningKey};

    let canonical = canonicalize_signed(signed).expect("canonicalize test signed payload");
    let sk = SigningKey::from_bytes(seed);
    let sig = sk.sign(canonical.as_bytes());
    let sig_b64url = base64::engine::general_purpose::URL_SAFE_NO_PAD.encode(sig.to_bytes());

    let manifest = serde_json::json!({
        "schema_version": super::manifest::SCHEMA_VERSION,
        "kid": kid,
        "signature": sig_b64url,
        "signed": signed,
    });
    serde_json::to_vec(&manifest).expect("serialize test manifest")
}

/// Convenience: sign with the PINNED test seed + kid (the happy path).
pub fn sign_manifest(signed: &Signed) -> Vec<u8> {
    sign_manifest_with(&TEST_SEED, TEST_KID, signed)
}

/// Parse a manifest that [`sign_manifest`] produced (for tests that then run the policy chain).
pub fn parse(bytes: &[u8]) -> Manifest {
    Manifest::parse(bytes).expect("parse test manifest")
}
